function sOwnership() {
  return CW('rs-ownership', {
    code: [['let s = String::from("hi");   // s가 소유', 'let s = String::from("hi");   // s owns it'], ['let t = s;                    // 이동', 'let t = s;                    // move'], 'println!("{s}");              // E0382', ['take(t);                      // 함수로 이동', 'take(t);                      // moved into fn'], ['// take가 끝나면 버퍼 해제', '// freed when take returns']],
    hl: [[0, 1, 'accent'], [1, 1, 'warn'], [2, 1, 'danger'], [3, 2, 'ok']],
    draw: (S) => {
      chip(S, 's', 19.0, .5, 2.2, 's', 'accent', 1, { h: .8, off: 2 }); chip(S, 'sx', 19.0, .5, 2.2, 's ✗', 'ink-3', 2, { h: .8 });
      cells(S, 'hb', 26.0, 1.0, [['h', 'accent'], ['i', 'accent']], 1); arw(S, 'sa', [21.3, .9], [25.9, 1.25], 1, { off: 2 });
      lbl(S, 'l1', 19.0, 2.6, ['값마다 주인은 하나 · s가 힙 버퍼의 주인이에요', 'every value has exactly one owner; s owns the heap buffer'], 'a', 1, { w: 12.4 });
      chip(S, 't', 19.0, 1.5, 2.2, 't', 'warn', 2, { h: .8 }); arw(S, 'ta', [21.3, 1.9], [25.9, 1.55], 2, { color: 'warn' });
      lbl(S, 'l2', 19.0, 4.0, ['let t = s는 24B 헤더만 옮기고 s를 무효로 · 버퍼는 복사하지 않고 이중 해제도 없어요', 'let t = s moves only the 24-byte header and invalidates s: no buffer copy, no double free'], 'w', 2, { w: 12.4 });
      mono(S, 'er', 19.0, 5.4, ['error[E0382]: borrow of moved value: `s`', 'value borrowed here after move'], 3, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l3', 19.0, 6.7, ['이동된 s를 쓰면 실행 전에 컴파일 오류 · 런타임 검사가 아니에요', 'using the moved s is a compile error, caught before running rather than checked at run time'], 'r', 3, { w: 12.4 });
      flow(S, 'tk', [['take(t)', 'accent', 19.0, 3.0], [['take 끝', 'take returns'], 'warn', 22.45, 4.6], ['drop → free', 'ok', 27.5, 3.9]], 8.1, 4);
      lbl(S, 'l4', 19.0, 9.3, ['함수에 넘겨도 이동 · 주인이 범위를 벗어나면 자동으로 해제(drop)', 'passing to a function moves too, and a value is dropped when its owner leaves scope'], 'g', 4, { w: 12.4 });
      lbl(S, 'm2', 1, 7.0, ['C++의 std::move와 달리 이동이 기본이고, 이동된 값은 아예 못 써요', 'unlike C++’s std::move, moving is the default and a moved-from value cannot be used at all'], 'w', 2, { w: 16.0, off: 4 });
      lbl(S, 'm4', 1, 7.0, ['GC 없이도 해제 시점을 컴파일러가 정확히 알아요', 'with no GC, the compiler still knows exactly when to free'], 'g', 4, { w: 16.0 });
    },
    notes: [['Rust에서 모든 값에는 주인(owner)인 변수가 딱 하나 있어요 · String::from("hi")는 힙에 바이트를 할당하고, 스택의 s에는 포인터, 길이, 용량으로 된 24바이트 헤더가 놓여 s가 그 버퍼의 주인이 돼요', 'in Rust every value has exactly one owner variable: String::from("hi") allocates bytes on the heap, and s on the stack holds a 24-byte header of pointer, length and capacity, making s the owner of that buffer'], ['let t = s는 헤더 24바이트만 t로 옮기고 s를 더 이상 쓸 수 없게 만들어요(이동) · 힙 버퍼는 복사되지 않고, 주인이 여전히 하나라서 두 변수가 같은 버퍼를 두 번 해제하는 일이 원천적으로 없어요', 'let t = s moves just the 24-byte header into t and makes s unusable (a move): the heap buffer is not copied, and since there is still only one owner, two variables can never free the same buffer twice'], ['이동된 s를 다시 쓰면 이 환경에서 error[E0382]: borrow of moved value: `s`로 컴파일이 실패했어요 · 이 검사는 실행 중이 아니라 컴파일 때 끝나서 실행 비용이 없어요', 'using the moved s again failed to compile here with error[E0382]: borrow of moved value: `s`, a check finished at compile time rather than at run time, so it costs nothing when running'], ['함수 인자로 넘기는 것도 이동이라, take(t) 뒤에는 t를 못 써요 · 주인이 범위를 벗어나면 컴파일러가 넣어 둔 drop이 불려 버퍼가 해제되므로, GC 없이도 메모리가 정확한 시점에 돌아가요', 'passing a function argument is also a move, so t is unusable after take(t), and when the owner leaves scope the drop the compiler inserted runs and frees the buffer, returning memory at precisely the right moment without a GC']],
    fin: [['값마다 주인은 하나, 대입과 전달은 이동', 'one owner per value; assignment and passing move it', 'rsx-xs rsx-a'], ['이동된 값은 컴파일러가 쓰지 못하게 막아요', 'the compiler forbids using moved values'], ['주인이 사라지면 자동으로 drop', 'values drop automatically when their owner goes away']],
    caps: [['하나의 주인', 'One owner'], ['이동', 'Moving'], ['E0382', 'E0382'], ['범위와 drop', 'Scope and drop'], ['소유권', 'Ownership']]
  });
}

