function sEnum() {
  return CW('rs-enum', {
    code: ['enum Shape { Circle(f64), Rect(f64, f64) }', ['let s = Shape::Rect(2.0, 3.0);   // 24바이트', 'let s = Shape::Rect(2.0, 3.0);   // 24 bytes'], 'let a = match s {', '    Shape::Circle(r) => 3.14 * r * r,', '    Shape::Rect(w, h) => w * h,', ['};                            // 누락 시 E0004', '};                            // else E0004']],
    hl: [[0, 2, 'accent'], [2, 3, 'ok'], [5, 1, 'danger'], [0, 6]],
    draw: (S) => {
      [['tag 0', 'r', '—'], ['tag 1', 'w', 'h']].forEach(([a, b, c], i) => { const y = .5 + i * .95; chip(S, 'tg' + i, 19.0, y, 2.8, a, 'warn', 1, { h: .8 }); chip(S, 'p' + i, 22.0, y, 4.4, b, 'accent', 1, { h: .8 }); chip(S, 'q' + i, 26.6, y, 4.4, c, c === '—' ? 'ink-3' : 'accent', 1, { h: .8 }); });
      T(S, 'sz', 19.0, 2.5, 'size_of::<Shape>() = 24', 'cz-mono rsx-tiny rsx-a', 1, { w: 12.4 });
      lbl(S, 'l1', 19.0, 3.1, ['enum은 태그 붙은 공용체 · 여러 모양 중 하나와 그 데이터를 담아요 (8B 태그 + 16B)', 'an enum is a tagged union holding one variant and its data (8 B tag + 16 B)'], 'a', 1, { w: 12.4 });
      flow(S, 'mf', [['tag', 'warn', 19.0, 2.2], ['jump', 'ok', 21.65, 2.4], ['w * h', 'ok', 24.5, 3.0]], 4.5, 2);
      lbl(S, 'l2', 19.0, 5.7, ['match는 태그로 분기하며 데이터를 꺼내 이름에 묶어요 · 값을 돌려주는 식이에요', 'match branches on the tag and binds the data to names; it is an expression with a value'], 'g', 2, { w: 12.4 });
      mono(S, 'er', 19.0, 7.1, ['error[E0004]: non-exhaustive patterns:', '`&Shape::Tri(_)` not covered'], 3, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l3', 19.0, 8.3, ['변형을 새로 추가하면 그걸 처리하지 않은 match가 모두 컴파일 오류로 드러나요', 'adding a variant turns every match that ignores it into a compile error'], 'r', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.75, ['if let, matches!, 가드(if)로 간단한 경우도 처리해요', 'if let, matches! and guards (if) handle simpler cases'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 8.1, ['Option<Box<T>>는 8바이트: null을 None으로 쓰는 니치 최적화', 'Option<Box<T>> is 8 bytes: the niche optimization uses null as None'], 'a', 4, { w: 16.0 });
    },
    notes: [['Rust의 enum은 C의 열거형보다 강해서, 각 변형이 서로 다른 데이터를 가질 수 있는 태그 붙은 공용체(합 타입)예요 · Shape는 Circle이면 반지름 하나, Rect면 너비와 높이를 담고, 어느 변형인지 나타내는 태그와 가장 큰 변형의 데이터 공간을 합쳐 24바이트예요', 'a Rust enum is stronger than a C enumeration: a tagged union (sum type) whose variants can carry different data, so Shape holds one radius for Circle or a width and height for Rect, totaling 24 bytes for the tag saying which variant it is plus room for the largest variant’s data'], ['match는 태그를 보고 해당 변형으로 분기하면서 안의 데이터를 r, w, h 같은 이름에 묶어요 · match는 값을 돌려주는 식이라 let a = match s { … }처럼 쓰고, 컴파일러는 이를 태그에 따른 점프로 만들어요', 'match looks at the tag, branches to the matching variant and binds its data to names such as r, w and h; being an expression that yields a value, it is used as in let a = match s { … }, and the compiler turns it into a jump on the tag'], ['match는 모든 경우를 빠짐없이 다뤄야 해요 · Shape에 Tri를 추가하자 이 환경에서 error[E0004]: non-exhaustive patterns: `&Shape::Tri(_)` not covered로 컴파일이 실패했어요 · 새 변형을 추가하면 처리를 빠뜨린 곳이 모두 드러나요', 'a match must cover every case: after adding Tri to Shape, compilation failed here with error[E0004]: non-exhaustive patterns: `&Shape::Tri(_)` not covered, so adding a variant exposes every place that forgot to handle it'], ['한 경우만 보면 if let Some(x) = …, 조건까지 보면 match의 가드(if)를 써요 · 컴파일러는 남는 비트 패턴을 태그로 써서, Option<Box<T>>는 null을 None으로 삼아 포인터와 같은 8바이트예요(니치 최적화)', 'for a single case use if let Some(x) = …, and for extra conditions a match guard (if); the compiler reuses spare bit patterns as tags, so Option<Box<T>> treats null as None and is the same 8 bytes as a pointer (the niche optimization)']],
    fin: [['enum = 변형마다 다른 데이터를 갖는 합 타입', 'an enum is a sum type whose variants carry different data', 'rsx-xs rsx-a'], ['match는 모든 경우를 강제해요', 'match enforces every case'], ['니치 최적화로 Option이 공짜가 되기도', 'the niche optimization can make Option free']],
    caps: [['태그 붙은 공용체', 'A tagged union'], ['match', 'match'], ['빠짐없는 검사', 'Exhaustiveness'], ['if let과 니치', 'if let and niches'], ['열거형과 패턴 매칭', 'Enums and pattern matching']]
  });
}

function sOption() {
  return CW('rs-option', {
    code: ['fn port(s: &str) -> Result<u16, Error> {', ['    let n = s.parse()?;       // Err면 반환', '    let n = s.parse()?;       // returns Err'], '    Ok(n)', '}', ['let x: Option<i32> = None;     // null 없음', 'let x: Option<i32> = None;     // no null'], 'x.unwrap_or(0);                // 0'],
    hl: [[4, 2, 'accent'], [0, 4, 'ok'], [1, 1, 'warn'], [5, 1, 'ok']],
    draw: (S) => {
      chip(S, 'so', 19.0, .5, 4.2, 'Some(i32)', 'ok', 1, { h: .8 }); chip(S, 'no', 23.4, .5, 2.6, 'None', 'ink-3', 1, { h: .8 }); T(S, 'os', 26.3, .6, 'Option<i32>: 8 B', 'cz-mono rsx-tiny rsx-a', 1, { w: 5.1 });
      lbl(S, 'l1', 19.0, 1.6, ['null이 없어요 · 없을 수 있는 값은 Option이고, 컴파일러가 None 처리를 강제해요', 'no null: a maybe-absent value is an Option, and the compiler forces None to be handled'], 'a', 1, { w: 12.4 });
      mono(S, 'rs', 19.0, 3.1, ['"8080"  → Ok(8080)', '"abc"   → Err(invalid digit found in string)', '"70000" → Err(number too large to fit …)'].map(t => t.replace(/ /g, ' ')), 2, { w: 12.4, dy: .55, c: 'rsx-g' });
      lbl(S, 'l2', 19.0, 4.9, ['실패할 수 있는 연산은 Result<T, E> · 오류는 예외가 아니라 값이에요 (이 환경의 결과)', 'fallible operations return Result<T, E>, so errors are values, not exceptions (results from here)'], 'g', 2, { w: 12.4 });
      flow(S, 'qf', [['parse()?', 'warn', 19.0, 3.2], ['Err(e)', 'danger', 22.65, 2.8], [['바로 return', 'return early'], 'warn', 25.9, 5.5]], 6.3, 3);
      lbl(S, 'l3', 19.0, 7.5, ['?는 Err이면 그 자리에서 반환하고 From으로 오류 타입도 바꿔요 · Go의 if err != nil을 한 글자로', '? returns the Err on the spot, converting it via From: Go’s if err != nil in one character'], 'w', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 8.9, ['unwrap_or, map, and_then으로 이어 쓰고 · unwrap은 None이면 panic이니 라이브러리에선 피해요', 'chain unwrap_or, map and and_then; unwrap panics on None, so avoid it in libraries'], 'g', 4, { w: 12.4 });
    },
    notes: [['Rust에는 null이 없어요 · 없을 수도 있는 값은 Some(값)이나 None인 Option<T>로 표현하고, 컴파일러가 None인 경우를 처리하지 않으면 값을 꺼내지 못하게 해요 · 니치 최적화 덕분에 Option<&T>는 포인터와 같은 크기이고, Option<i32>는 8바이트예요', 'Rust has no null: a value that may be absent is an Option<T> of Some(value) or None, and the compiler will not let you take the value out without handling None; thanks to the niche optimization, Option<&T> is pointer-sized, and Option<i32> is 8 bytes'], ['실패할 수 있는 연산은 Ok(값)이나 Err(오류)인 Result<T, E>를 돌려줘요 · 이 환경에서 "8080"은 Ok(8080), "abc"는 invalid digit found in string, "70000"은 u16 범위를 넘어 number too large to fit in target type 오류였어요', 'fallible operations return a Result<T, E> of Ok(value) or Err(error): here "8080" gave Ok(8080), "abc" gave invalid digit found in string, and "70000", beyond u16, gave number too large to fit in target type'], ['s.parse()? 끝의 ?는 결과가 Ok면 값을 꺼내고, Err면 그 오류를 함수의 반환값으로 바로 돌려줘요 · 이때 From 트레이트로 오류 타입을 함수의 오류 타입으로 바꿔 줘서, 오류 전파가 한 글자로 끝나요', 'the ? at the end of s.parse()? takes out the value on Ok and, on Err, immediately returns that error from the function, converting it to the function’s error type through the From trait, so error propagation takes a single character'], ['unwrap_or(0), map, and_then, ok_or 같은 메서드로 값을 이어서 다뤄요 · unwrap()과 expect()는 None이나 Err이면 panic을 내므로, 테스트나 절대 실패하지 않는 경우에만 쓰고 라이브러리 코드에서는 피해요', 'methods such as unwrap_or(0), map, and_then and ok_or chain operations on these values, while unwrap() and expect() panic on None or Err, so they are kept for tests and cases that truly cannot fail and avoided in library code']],
    fin: [['null 대신 Option, 예외 대신 Result', 'Option instead of null, Result instead of exceptions', 'rsx-xs rsx-a'], ['?로 오류를 짧게 전파해요', 'propagate errors briefly with ?'], ['unwrap은 확실할 때만', 'unwrap only when certain']],
    caps: [['Option', 'Option'], ['Result', 'Result'], ['? 연산자', 'The ? operator'], ['조합 메서드', 'Combinators'], ['Option과 Result', 'Option and Result']]
  });
}

