      lbl(S, 'l2', 19.0, 5.2, ['T: Area로 제약하면 컴파일 때 구체 타입을 알아서 직접 호출하고 인라인해요', 'bounding T: Area lets the compiler know the concrete type, call directly and inline'], 'g', 2, { w: 12.4 });
