function sBox() {
  return CW('rs-box', {
    code: [['let b = Box::new(5);          // 힙의 i32', 'let b = Box::new(5);          // heap i32'], 'enum List { Cons(i32, List), Nil }   // E0072', 'enum List { Cons(i32, Box<List>), Nil }', ['fn make() -> Box<dyn Area>     // 크기 모름', 'fn make() -> Box<dyn Area>     // unsized'], ['// b가 범위를 벗어나면 free', '// freed when b leaves scope']],
    hl: [[0, 1, 'accent'], [1, 1, 'danger'], [2, 1, 'ok'], [3, 2, 'ok']],
    draw: (S) => {
      chip(S, 'b', 19.0, .5, 2.4, 'b', 'accent', 1, { h: .8 }); arw(S, 'ba', [21.5, .9], [23.9, .9], 1); chip(S, 'hv', 24.0, .5, 2.4, '5', 'ok', 1, { h: .8 }); T(S, 'ht', 26.8, .6, ['← 힙', '← heap'], 'rsx-tiny rsx-g', 1, { w: 2.4 });
      T(S, 'bs', 19.0, 1.45, 'Box<i32>: 8 B', 'cz-mono rsx-tiny rsx-a', 1, { w: 5.0 });
      lbl(S, 'l1', 19.0, 2.0, ['Box는 힙에 있는 값을 소유하는 8바이트 포인터 · 범위를 벗어나면 해제돼요', 'a Box is an 8-byte pointer owning a value on the heap, freed when it leaves scope'], 'a', 1, { w: 12.4 });
      mono(S, 'er', 19.0, 3.4, ['error[E0072]: recursive type `List`', 'has infinite size'], 2, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l2', 19.0, 4.6, ['List 안에 List가 그대로 들어가면 크기가 끝없이 커져요 · 컴파일러가 Box를 쓰라고 알려 줘요', 'a List directly inside a List would be endlessly large, and the compiler suggests a Box'], 'r', 2, { w: 12.4 });
      flow(S, 'ls', [['Cons 1', 'accent', 19.0, 2.8], ['Cons 2', 'accent', 22.25, 2.8], ['Cons 3', 'accent', 25.5, 2.8], ['Nil', 'ink-3', 28.75, 2.65]], 6.0, 3);
      lbl(S, 'l3', 19.0, 7.2, ['Box<List>는 크기가 정해진 포인터 · 노드들이 힙에서 사슬로 이어져요', 'Box<List> is a pointer of known size, so the nodes chain together on the heap'], 'g', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 8.6, ['크기를 모르는 dyn Trait를 담거나 큰 값을 복사 없이 옮길 때도 Box', 'Box also holds unsized dyn Traits and moves large values without copying'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 7.0, ['비용은 malloc과 free를 직접 쓰는 것과 같아요 · GC가 끼지 않아요', 'it costs the same as calling malloc and free yourself, with no GC involved'], 'a', 4, { w: 16.0 });
    },
    notes: [['Box<T>는 값을 힙에 두고 그 값을 혼자 소유하는 가장 단순한 스마트 포인터예요 · Box::new(5)는 힙에 i32를 할당하고, 스택의 b는 8바이트 포인터예요 · b가 범위를 벗어나면 Drop이 힙 메모리를 해제해요', 'Box<T> is the simplest smart pointer, putting a value on the heap and owning it alone: Box::new(5) allocates an i32 on the heap, b on the stack is an 8-byte pointer, and when b leaves scope, Drop frees the heap memory'], ['enum List { Cons(i32, List), Nil }처럼 자기 자신을 직접 담는 타입은 크기가 무한히 커져서, 이 환경에서 error[E0072]: recursive type `List` has infinite size와 함께 Box, Rc, & 같은 간접 참조를 넣으라는 도움말이 나왔어요', 'a type that directly contains itself, such as enum List { Cons(i32, List), Nil }, would be infinitely large, and here it failed with error[E0072]: recursive type `List` has infinite size, plus a hint to insert indirection such as Box, Rc or &'], ['Cons(i32, Box<List>)로 바꾸면 다음 노드 자리에 크기가 정해진 8바이트 포인터가 들어가서 컴파일돼요 · 노드들은 힙에 따로 할당되어 포인터로 이어진 연결 리스트가 돼요', 'changing it to Cons(i32, Box<List>) puts a pointer of known size, 8 bytes, where the next node goes, so it compiles, and the nodes become a linked list allocated separately on the heap and joined by pointers'], ['Box는 크기를 컴파일 때 알 수 없는 dyn Trait 같은 값을 담을 때, 그리고 큰 값을 스택에서 복사하지 않고 포인터만 옮기고 싶을 때도 써요 · 비용은 malloc과 free를 직접 부르는 것과 같아요', 'Box is also used to hold values whose size is unknown at compile time, such as a dyn Trait, and to move large values by pointer instead of copying them on the stack, at the same cost as calling malloc and free directly']],
    fin: [['Box = 힙 값을 혼자 소유하는 포인터', 'a Box is a pointer that solely owns a heap value', 'rsx-xs rsx-a'], ['재귀 타입의 크기를 정해 줘요', 'it gives recursive types a known size'], ['dyn Trait를 담는 그릇', 'it is the container for dyn Traits']],
    caps: [['힙의 값', 'A value on the heap'], ['E0072', 'E0072'], ['재귀 타입', 'Recursive types'], ['쓰임새', 'Uses'], ['Box', 'Box']]
  });
}

