      chip(S, 'w', 19.0, 1.0, 2.2, 'w', 'warn', 3, { h: .8 }); arw(S, 'wa', [21.3, 1.4], [23.5, 1.3], 3, { color: 'warn', dash: 1 });
      lbl(S, 'l1', 19.0, 2.8, ['Rc는 참조 수를 세는 공유 소유 · clone은 복사가 아니라 수만 1 올려요', 'Rc is shared ownership with a reference count; clone copies nothing and just adds 1'], 'a', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.2, ['clone마다 +1, drop마다 −1 · 강한 수가 0이 되면 값이 해제돼요', 'each clone adds 1 and each drop subtracts 1; at a strong count of 0 the value is dropped'], 'w', 2, { w: 12.4 });
