      lbl(S, 'l3', 19.0, 6.9, ['Weak는 수에 넣지 않는 약한 참조 · upgrade로 아직 살아 있는지 확인해요', 'Weak is a reference left out of the count; upgrade checks whether the value is still alive'], 'g', 3, { w: 12.4 });
      chip(S, 'cx', 19.0, 8.2, 2.4, 'x', 'danger', 4, { h: .8 }); chip(S, 'cy', 23.0, 8.2, 2.4, 'y', 'danger', 4, { h: .8 });
