    code: ['let r = Rc::new(5);', 'thread::spawn(move || r);       // E0277', 'let a = Arc::new(5);', 'thread::spawn(move || a);       // OK', ['// Send: 다른 스레드로 넘겨도 됨', '// Send: safe to move to another thread'], ['// Sync: &T를 함께 봐도 됨', '// Sync: &T safe to share across threads']],
