function sModule() {
  return CW('rs-module', {
    code: ['mod net {', ['    fn secret() {}      // 기본은 비공개', '    fn secret() {}      // private by default'], '    pub fn connect() {}', '    pub(crate) fn helper() {}', '}', 'net::secret();            // E0603'],
    hl: [[0, 5, 'accent'], [1, 1, 'warn'], [5, 1, 'danger'], [3, 1, 'ok']],
    draw: (S) => {
      mono(S, 'tr', 19.0, .5, nbs(['crate', '└─ net', '   ├─ secret()', '   ├─ connect()   pub', '   └─ helper()    pub(crate)']), 1, { w: 12.4, dy: .55, c: 'rsx-a' });
      lbl(S, 'l1', 19.0, 3.4, ['모듈은 이름의 트리 · crate::net::connect처럼 경로로 가리켜요', 'modules form a tree of names, reached by paths such as crate::net::connect'], 'a', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['모든 항목은 기본이 비공개 · 같은 모듈과 자식만 보고, pub를 붙여야 밖에서 써요', 'everything is private by default, visible to its module and children until marked pub'], 'w', 2, { w: 12.4 });
      T(S, 'er', 19.0, 6.2, 'error[E0603]: function `secret` is private', 'cz-mono rsx-tiny rsx-r', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.8, ['비공개 함수를 밖에서 부르면 컴파일 오류 · 공개 API를 작게 지킬 수 있어요', 'calling a private function from outside fails to compile, keeping the public API small'], 'r', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 8.2, ['pub(crate)는 크레이트 안에서만, pub use로 다시 내보내 경로를 정리해요', 'pub(crate) limits visibility to the crate, and pub use re-exports to tidy paths'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 8.1, ['mod net;이라고 쓰면 net.rs나 net/mod.rs 파일에서 내용을 읽어요', 'writing mod net; loads the contents from net.rs or net/mod.rs'], 'a', 1, { w: 16.0 });
    },
    notes: [['크레이트 안의 코드는 모듈로 나뉘고, 모듈은 crate를 뿌리로 하는 이름의 트리를 이뤄요 · mod net { … }으로 바로 정의하거나 mod net;으로 net.rs 파일을 불러오고, crate::net::connect 같은 경로로 가리켜요', 'code within a crate is divided into modules forming a tree of names rooted at crate: a module is defined inline as mod net { … } or loaded from net.rs with mod net;, and items are referred to by paths such as crate::net::connect'], ['Rust의 모든 항목은 기본이 비공개예요 · 비공개 항목은 같은 모듈과 그 자식 모듈에서만 보이고, 밖에서 쓰게 하려면 pub를 붙여요 · 그래서 공개 API는 일부러 고른 것만 남아요', 'every Rust item is private by default, visible only within its own module and that module’s children, and it must be marked pub to be used from outside, so the public API contains only what was deliberately chosen'], ['모듈 밖에서 비공개 함수 net::secret()을 부르자 이 환경에서 error[E0603]: function `secret` is private가 났어요 · 내부 구현을 마음대로 바꿔도 바깥 코드가 깨지지 않게 컴파일러가 지켜 줘요', 'calling the private net::secret() from outside the module produced error[E0603]: function `secret` is private here, so the compiler guarantees that internals can change freely without breaking outside code'], ['pub(crate)는 같은 크레이트 안에서만 공개하고, pub(super)는 부모 모듈까지만 공개해요 · 깊은 경로에 있는 항목은 pub use로 다시 내보내 사용자가 짧은 경로로 쓰게 하고, 큰 프로젝트는 여러 크레이트를 워크스페이스로 묶어요', 'pub(crate) exposes an item only within the same crate and pub(super) only to the parent module; items deep in the tree are re-exported with pub use so users get short paths, and large projects group several crates into a workspace']],
    fin: [['모듈 = 이름의 트리, 기본은 비공개', 'modules form a tree of names, private by default', 'rsx-xs rsx-a'], ['pub, pub(crate)로 단계별 공개', 'pub and pub(crate) open visibility step by step'], ['pub use로 경로를 정리해요', 'tidy paths with pub use']],
    caps: [['모듈 트리', 'The module tree'], ['기본은 비공개', 'Private by default'], ['E0603', 'E0603'], ['공개 범위 조절', 'Tuning visibility'], ['모듈과 가시성', 'Modules and visibility']]
  });
}

function sTestR() {
  return CW('rs-test', {
    code: ['#[test]', 'fn adds() { assert_eq!(add(2, 2), 4); }', '#[test] #[should_panic]', 'fn overflow() { 255u8 + black_box(1); }', ['/// assert_eq!(add(2, 3), 5);   // 문서 테스트', '/// assert_eq!(add(2, 3), 5);   // doc test'], '$ cargo test'],
    hl: [[0, 2, 'accent'], [2, 2, 'warn'], [4, 1, 'ok'], [5, 1, 'ok']],
    draw: (S) => {
      mono(S, 'r1', 19.0, .5, ['running 3 tests', 'test tests::adds ... ok', 'test tests::macro_works ... ok'], 1, { w: 12.4, dy: .55, c: 'rsx-g' });
      lbl(S, 'l1', 19.0, 2.3, ['#[test] 함수는 같은 파일의 tests 모듈에 · 비공개 함수도 테스트할 수 있어요', '#[test] functions sit in a tests module in the same file, where private functions can be tested'], 'a', 1, { w: 12.4 });
      mono(S, 'sp', 19.0, 3.8, nbs(['test tests::overflow_panics', '  - should panic ... ok']), 2, { w: 12.4, dy: .55, c: 'rsx-w' });
      lbl(S, 'l2', 19.0, 5.0, ['디버그 빌드는 정수 넘침을 검사해서 255u8 + 1이 panic · should_panic이 그걸 확인해요', 'debug builds check integer overflow, so 255u8 + 1 panics, and should_panic verifies it'], 'w', 2, { w: 12.4 });
      T(S, 'dt', 19.0, 6.5, 'test src/lib.rs - add (line 3) ... ok', 'cz-mono rsx-tiny rsx-g', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 7.1, ['문서 주석 속 예제도 컴파일해 실행해요 · 문서가 코드와 어긋날 수 없어요', 'examples inside doc comments are compiled and run too, so docs cannot drift from the code'], 'g', 3, { w: 12.4 });
      T(S, 'rs', 19.0, 8.5, 'test result: ok. 3 passed; 0 failed', 'cz-mono rsx-tiny rsx-g', 4, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.1, ['테스트는 기본으로 병렬 실행 · 통합 테스트는 tests/ 디렉터리에 (이 환경의 실제 출력)', 'tests run in parallel by default; integration tests go in tests/ (actual output here)'], 'g', 4, { w: 12.4 });
    },
    notes: [['Rust의 단위 테스트는 #[test]를 붙인 함수예요 · 보통 같은 파일 아래쪽의 #[cfg(test)] mod tests 안에 두어서, 테스트할 때만 컴파일되고 비공개 함수도 테스트할 수 있어요 · assert_eq!가 실패하면 기대값과 실제값을 함께 보여 줘요', 'Rust unit tests are functions marked #[test], usually placed in a #[cfg(test)] mod tests at the bottom of the same file, so they compile only for testing and can reach private functions, and a failing assert_eq! shows both the expected and actual values'], ['#[should_panic]은 panic이 나야 통과하는 테스트예요 · 디버그 빌드는 정수 넘침을 검사하므로 255u8 + 1이 attempt to add with overflow panic을 내고, 이 환경에서도 should panic ... ok로 통과했어요 · 릴리스 빌드에서는 기본으로 넘침이 감싸져요', '#[should_panic] marks a test that passes only if it panics: debug builds check integer overflow, so 255u8 + 1 panics with attempt to add with overflow, and here it passed as should panic ... ok, while release builds wrap on overflow by default'], ['/// 문서 주석 안의 코드 블록은 문서 테스트가 되어 cargo test가 실제로 컴파일하고 실행해요 · 이 환경에서도 test src/lib.rs - add (line 3) ... ok가 나왔어요 · 그래서 문서에 적힌 예제가 코드와 어긋날 수 없어요', 'code blocks inside /// doc comments become doc tests that cargo test actually compiles and runs, and here it printed test src/lib.rs - add (line 3) ... ok, so examples written in the docs can never drift from the code'], ['cargo test는 단위 테스트, tests/ 디렉터리의 통합 테스트, 문서 테스트를 모두 찾아 기본으로 병렬로 실행해요 · 이 환경에서 3개의 단위 테스트와 1개의 문서 테스트가 모두 통과했어요 · 벤치마크는 criterion 크레이트를 많이 써요', 'cargo test finds unit tests, integration tests in the tests/ directory and doc tests and runs them in parallel by default, and here all 3 unit tests and the 1 doc test passed, while benchmarks commonly use the criterion crate']],
    fin: [['#[test], 통합 테스트, 문서 테스트를 cargo test 하나로', '#[test], integration and doc tests all run with cargo test', 'rsx-xs rsx-a'], ['문서의 예제가 곧 테스트', 'the examples in the docs are tests'], ['should_panic으로 실패 경로도 검사해요', 'should_panic checks failure paths too']],
    caps: [['단위 테스트', 'Unit tests'], ['should_panic', 'should_panic'], ['문서 테스트', 'Doc tests'], ['cargo test', 'cargo test'], ['테스트', 'Testing']]
  });
}

function sClippy() {
  return CW('rs-clippy', {
    code: ['pub fn total(v: &Vec<i32>) -> i32 {', '    let mut s = 0;', '    for i in 0..v.len() { s += v[i]; }', '    if pos == true { s } else { 0 } }', '$ cargo clippy && cargo fmt'],
    hl: [[0, 1, 'warn'], [2, 1, 'warn'], [3, 1, 'warn'], [4, 1, 'ok']],
    draw: (S) => {
      mono(S, 'w1', 19.0, .5, ['warning: writing `&Vec` instead of `&[_]`', 'clippy::ptr_arg'], 1, { w: 12.4, dy: .55, c: 'rsx-w' });
      lbl(S, 'l1', 19.0, 1.8, ['clippy는 수백 개의 린트로 관용적이지 않거나 느린 코드를 짚어요 · &Vec 대신 &[i32]', 'clippy flags unidiomatic or slow code with hundreds of lints: &[i32] instead of &Vec'], 'a', 1, { w: 12.4 });
      mono(S, 'w2', 19.0, 3.3, ['the loop variable `i` is only used', 'to index `v`   (needless_range_loop)'], 2, { w: 12.4, dy: .55, c: 'rsx-w' });
      lbl(S, 'l2', 19.0, 4.5, ['인덱스로만 쓰는 반복 변수는 for x in v로 · 반복자가 더 안전하고 읽기 쉬워요', 'a loop variable used only to index becomes for x in v, which is safer and clearer'], 'w', 2, { w: 12.4 });
      mono(S, 'w3', 19.0, 5.9, ['equality checks against true', 'are unnecessary   (bool_comparison)'], 3, { w: 12.4, dy: .55, c: 'rsx-w' });
      lbl(S, 'l3', 19.0, 7.1, ['cargo clippy --fix는 고칠 수 있는 것을 자동으로 고쳐요 (이 환경의 실제 경고)', 'cargo clippy --fix applies the fixes it can automatically (actual warnings here)'], 'g', 3, { w: 12.4 });
      flow(S, 'ci', [['cargo fmt', 'accent', 19.0, 3.4], ['clippy -D warnings', 'warn', 22.85, 5.6], ['CI', 'ok', 28.9, 2.5]], 8.4, 4);
      lbl(S, 'l4', 19.0, 9.6, ['rustfmt가 형식을 하나로 · CI에서 fmt --check와 clippy 경고를 오류로 다뤄요', 'rustfmt fixes one format, and CI runs fmt --check and treats clippy warnings as errors'], 'g', 4, { w: 12.4 });
    },
    notes: [['clippy는 Rust 공식 린터로, 컴파일은 되지만 관용적이지 않거나 느리거나 실수일 가능성이 큰 코드를 수백 가지 규칙으로 짚어 줘요 · 이 환경에서 &Vec<i32> 매개변수에 대해 ptr_arg 경고가 나왔어요 · &[i32]로 받으면 배열과 슬라이스도 받을 수 있어요', 'clippy is Rust’s official linter, flagging code that compiles but is unidiomatic, slow or likely a mistake with hundreds of rules: here it raised ptr_arg for a &Vec<i32> parameter, since taking &[i32] also accepts arrays and slices'], ['for i in 0..v.len()처럼 인덱스로만 쓰는 반복 변수에는 needless_range_loop 경고가 나왔어요 · for x in v나 v.iter()로 바꾸면 경계 검사와 범위 실수가 사라지고 읽기도 쉬워요', 'a loop variable used only for indexing, as in for i in 0..v.len(), triggered needless_range_loop, and switching to for x in v or v.iter() removes bounds checks and range mistakes while reading better'], ['pos == true 같은 비교에는 bool_comparison 경고가 나왔어요 · cargo clippy --fix는 이런 것 중 기계적으로 고칠 수 있는 것을 자동으로 고쳐 줘요 · 경고마다 설명 문서의 링크가 함께 나와요', 'a comparison such as pos == true triggered bool_comparison; cargo clippy --fix applies the mechanically fixable ones automatically, and every warning comes with a link to its documentation'], ['rustfmt(cargo fmt)는 Go의 gofmt처럼 코드 형식을 하나로 정해 스타일 논쟁을 없애요 · 보통 CI에서 cargo fmt --check로 형식을 확인하고, cargo clippy -- -D warnings로 경고를 오류로 다뤄 빌드를 실패시켜요', 'rustfmt (cargo fmt), like Go’s gofmt, settles a single code format and ends style debates, and CI typically verifies formatting with cargo fmt --check and fails the build on warnings with cargo clippy -- -D warnings']],
    fin: [['clippy = 컴파일되는 실수를 잡는 린터', 'clippy is a linter for mistakes that compile', 'rsx-xs rsx-a'], ['--fix로 자동 수정', 'auto-fix with --fix'], ['CI에서 fmt와 clippy를 강제해요', 'enforce fmt and clippy in CI']],
    caps: [['ptr_arg', 'ptr_arg'], ['needless_range_loop', 'needless_range_loop'], ['bool_comparison과 --fix', 'bool_comparison and --fix'], ['rustfmt와 CI', 'rustfmt and CI'], ['clippy와 rustfmt', 'clippy and rustfmt']]
  });
}

function sMacro() {
  return CW('rs-macro', {
    code: ['macro_rules! maxm {', '    ($x:expr) => { $x };', '    ($x:expr, $($rest:expr),+) =>', '        { max($x, maxm!($($rest),+)) };', '}', 'maxm!(3, 9, 4)              // 9'],
    hl: [[0, 5, 'accent'], [2, 2, 'ok'], [5, 1, 'warn'], [0, 6]],
    draw: (S) => {
      flow(S, 'mf', [['maxm!(3, 9, 4)', 'accent', 19.0, 5.0], [['패턴 일치', 'match'], 'warn', 24.45, 3.0], [['코드 생성', 'expand'], 'ok', 27.9, 3.5]], .5, 1);
      lbl(S, 'l1', 19.0, 1.7, ['macro_rules!는 코드 조각을 패턴으로 받아 컴파일 때 코드를 만들어요 · println!, vec!도 매크로', 'macro_rules! matches code by pattern and expands it at compile time, like println!'], 'a', 1, { w: 12.4 });
      mono(S, 'ex', 19.0, 3.2, ['maxm!(3, 9, 4)', '→ max(3, maxm!(9, 4))', '→ max(3, max(9, maxm!(4)))', '→ 9'], 2, { w: 12.4, dy: .55, c: 'rsx-g' });
      lbl(S, 'l2', 19.0, 5.5, ['$(...),+ 반복으로 인자가 몇 개든 받아 재귀로 펼쳐요 (테스트로 확인: 9)', '$(...),+ takes any number of arguments and expands recursively (tested: 9)'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.9, ['매크로 안의 변수는 호출한 쪽 변수와 섞이지 않아요(위생성) · 펼친 결과도 타입 검사를 받아요', 'macro variables never clash with the caller’s (hygiene); expansions are type-checked'], 'w', 3, { w: 12.4 });
      chip(S, 'dv', 19.0, 8.3, 6.4, 'derive(Debug)', 'ok', 4, { h: .8 }); chip(S, 'tm', 25.6, 8.3, 5.6, 'tokio::main', 'ok', 4, { h: .8 });
      lbl(S, 'l4', 19.0, 9.3, ['derive와 속성 매크로는 토큰을 받아 코드를 내놓는 절차적 매크로 · 대가는 컴파일 시간', 'derive and attribute macros are procedural: they take tokens and emit code, at a compile-time cost'], 'g', 4, { w: 12.4 });
    },
    notes: [['Rust의 매크로는 이름 뒤의 !로 구별해요 · println!, vec!, format!이 모두 매크로예요 · macro_rules!로 만드는 선언적 매크로는 호출된 코드 조각을 $x:expr 같은 패턴으로 받아, 컴파일할 때 그 자리에 새 코드를 만들어 넣어요', 'Rust macros are recognized by the ! after their name, and println!, vec! and format! are all macros; declarative macros built with macro_rules! receive the code fragment they are called with through patterns such as $x:expr and generate new code in its place at compile time'], ['$($rest:expr),+는 쉼표로 구분된 식이 하나 이상 반복되는 패턴이에요 · maxm!(3, 9, 4)는 max(3, maxm!(9, 4))로, 다시 max(3, max(9, 4))로 재귀적으로 펼쳐져서, 인자 개수와 상관없이 하나의 매크로로 처리돼요 · 이 환경의 테스트에서도 9가 나왔어요', '$($rest:expr),+ is a pattern for one or more comma-separated expressions, so maxm!(3, 9, 4) expands recursively to max(3, maxm!(9, 4)) and then max(3, max(9, 4)), handling any number of arguments with one macro, and the test here produced 9'], ['C의 #define과 달리 Rust 매크로는 텍스트가 아니라 토큰 트리를 다루고 위생적이에요 · 매크로 안에서 만든 변수는 호출한 쪽의 같은 이름 변수와 섞이지 않고, 펼친 결과는 보통 코드처럼 타입 검사를 받아요', 'unlike C’s #define, Rust macros work on token trees rather than text and are hygienic: variables created inside a macro never collide with same-named variables at the call site, and the expansion is type-checked like ordinary code'], ['#[derive(Debug)]나 #[tokio::main]은 절차적 매크로예요 · 컴파일러가 코드의 토큰을 Rust 함수에 넘기면 그 함수가 새 코드를 만들어 돌려줘요 · serde의 Serialize 같은 강력한 기능이 이렇게 만들어지지만, 컴파일 시간이 늘어나는 대가가 있어요', '#[derive(Debug)] and #[tokio::main] are procedural macros: the compiler hands the code’s tokens to a Rust function, which returns newly generated code, which is how powerful features such as serde’s Serialize are built, at the cost of longer compile times']],
    fin: [['매크로 = 컴파일 때 코드를 만드는 코드', 'macros are code that writes code at compile time', 'rsx-xs rsx-a'], ['토큰 기반이라 위생적이에요', 'they are token-based and hygienic'], ['함수로 될 땐 함수를 먼저', 'prefer a function when one will do']],
    caps: [['선언적 매크로', 'Declarative macros'], ['반복과 재귀', 'Repetition and recursion'], ['위생성', 'Hygiene'], ['절차적 매크로', 'Procedural macros'], ['매크로', 'Macros']]
  });
}
/* ===== Rust · 6. in practice ===== */
const rbars = (S, k, y, rows, st) => rows.forEach(([n, v, c, t], i) => { const yy = y + i * .55; T(S, k + 'n' + i, 19.0, yy, n, 'cz-mono rsx-tiny', st, { w: 3.2 }); hbar(S, k + 'b' + i, 22.3, yy + .05, v, c, st, { h: .42 }); T(S, k + 'v' + i, 22.5 + v, yy, t, 'cz-mono rsx-tiny', st, { w: 3.0 }); });

function sIter() {
  return CW('rs-iter', {
    code: [['let it = v.iter().map(|x| x * 2); // 지연', 'let it = v.iter().map(|x| x * 2); // lazy'], 'let out: Vec<i32> = it.collect(); // [2,4,6]', '(1..).filter(|n| n % 7 == 0).take(3)', '(1..).map(|x| x * x).find(|&y| y > 50) // 64', ['// 체인 = 손으로 쓴 루프 (44ms)', '// chain = hand loop (44 ms)']],
    hl: [[0, 1, 'accent'], [1, 1, 'ok'], [2, 2, 'warn'], [4, 1, 'ok']],
    draw: (S) => {
      flow(S, 'if', [['v.iter()', 'accent', 19.0, 3.4], ['.map(f)', 'warn', 22.85, 3.0], [['실행 안 함', 'not run'], 'ink-3', 26.3, 5.1]], .5, 1);
      lbl(S, 'l1', 19.0, 1.7, ['map은 계획만 세운 값을 만들어요 · 클로저 안의 println이 아직 한 줄도 안 찍혔어요', 'map only builds a plan: the println inside the closure has printed nothing yet'], 'a', 1, { w: 12.4 });
      mono(S, 'o', 19.0, 3.2, ['created', 'map 1 → map 2 → map 3', '[2, 4, 6]'], 2, { w: 12.4, dy: .55, c: 'rsx-g' });
      lbl(S, 'l2', 19.0, 4.9, ['collect, sum, for 같은 소비자가 당길 때 원소가 하나씩 흘러가요 (실제 출력 순서)', 'consumers like collect or for pull items through one at a time (actual output)'], 'g', 2, { w: 12.4 });
      cells(S, 'tk', 19.0, 6.4, [['7', 'warn'], ['14', 'warn'], ['21', 'warn']], 3, { dx: 1.25, w: 1.05 });
      T(S, 'fd', 23.2, 6.55, 'find → 64 · 8 calls', 'cz-mono rsx-tiny rsx-w', 3, { w: 8.0 });
      lbl(S, 'l3', 19.0, 7.3, ['무한 범위도 take(3)에서 멈추고, find는 64를 찾자 8번 만에 멈췄어요', 'an infinite range stops at take(3), and find stopped at 64 after 8 calls'], 'w', 3, { w: 12.4 });
      rbars(S, 'eq', 8.9, [['chain', 4.4, 'ok', '44 ms'], ['loop', 4.4, 'ink-3', '44 ms']], 4);
      lbl(S, 'l4', 19.0, 10.1, ['반복자 체인은 손으로 쓴 루프만큼 빨라요 (실측) · 비용 없는 추상화', 'an iterator chain runs as fast as a hand loop (measured): a zero-cost abstraction'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 7.0, ['Iterator는 next() 하나만 구현하면 map, filter, zip 같은 수십 개 메서드가 따라와요', 'implementing just next() for Iterator brings dozens of methods such as map, filter and zip'], 'a', 4, { w: 16.0 });
    },
    notes: [['v.iter().map(|x| x * 2)는 아무것도 계산하지 않아요 · map은 원래 반복자와 클로저를 담은 Map 값을 돌려줄 뿐이에요 · 이 환경에서 map의 클로저 안에 println을 넣어도, 만든 직후에는 한 줄도 찍히지 않았어요', 'v.iter().map(|x| x * 2) computes nothing: map merely returns a Map value holding the original iterator and the closure, and here, even with a println inside the closure, nothing was printed right after creating it'], ['collect, sum, for 반복문처럼 값을 소비하는 쪽이 next()를 부를 때 원소가 하나씩 체인을 통과해요 · 실제 출력도 created가 먼저 찍히고 그다음 map 1, map 2, map 3, 마지막에 [2, 4, 6]이 나왔어요 · 중간 Vec은 만들어지지 않아요', 'elements pass through the chain one at a time as a consumer such as collect, sum or a for loop calls next(): the actual output printed created first, then map 1, map 2, map 3 and finally [2, 4, 6], with no intermediate Vec built'], ['필요한 만큼만 당기므로 (1..) 같은 무한 범위도 쓸 수 있어요 · filter와 take(3)으로 [7, 14, 21]을 얻었고, map(x * x).find(y > 50)은 64를 찾자 멈춰서 클로저가 딱 8번만 불렸어요', 'since only as much as needed is pulled, even an infinite range such as (1..) works: filter with take(3) gave [7, 14, 21], and map(x * x).find(y > 50) stopped on finding 64, calling the closure exactly 8 times'], ['컴파일러가 체인 전체를 인라인해 하나의 루프로 만들어요 · 2천만 원소에서 filter, map, sum 체인이 44ms, 같은 일을 하는 인덱스 루프도 44ms였어요 (--release) · 반복자는 경계 검사도 필요 없어서 안전하면서 빨라요', 'the compiler inlines the whole chain into a single loop: over 20 million elements, a filter, map and sum chain took 44 ms and an index loop doing the same took 44 ms (--release), and since iterators need no bounds checks they are both safe and fast']],
    fin: [['어댑터는 지연, 소비자가 당겨요', 'adapters are lazy, and consumers pull', 'rsx-xs rsx-a'], ['필요한 만큼만 계산해요', 'only what is needed is computed'], ['체인 = 손으로 쓴 루프의 속도', 'a chain runs at hand-loop speed']],
    caps: [['지연 어댑터', 'Lazy adapters'], ['소비자가 당긴다', 'Consumers pull'], ['무한 범위와 단락', 'Infinite ranges and short-circuits'], ['비용 없는 추상화', 'Zero-cost abstraction'], ['반복자', 'Iterators']]
  });
}

function sClosure() {
  return CW('rs-closure', {
    code: ['let greet = || println!("{name}");   // Fn', 'let mut inc = || n += 1;             // FnMut', 'let eat = move || drop(name);        // FnOnce', 'eat(); eat();                        // E0382', 'fn adder(k: i32) -> impl Fn(i32) -> i32', '    { move |x| x + k }               // 4B'],
    hl: [[0, 1, 'accent'], [1, 1, 'warn'], [2, 2, 'danger'], [4, 2, 'ok']],
    draw: (S) => {
      cells(S, 'tr', 19.0, .5, [['Fn', 'accent'], ['FnMut', 'warn'], ['FnOnce', 'danger']], 1, { dx: 4.2, w: 3.9 });
      mono(S, 'tc', 19.0, 1.45, nbs(['  &T            &mut T          T (move)']), 1, { w: 12.4 });
      lbl(S, 'l1', 19.0, 2.1, ['캡처를 어떻게 쓰느냐로 정해져요 · 읽기만 하면 Fn, 바꾸면 FnMut, 소비하면 FnOnce', 'the use of captures decides it: read → Fn, mutate → FnMut, consume → FnOnce'], 'a', 1, { w: 12.4 });
      mono(S, 'e1', 19.0, 3.6, ['error[E0594]: cannot assign to `n`, as it', 'is a captured variable in a `Fn` closure'], 2, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l2', 19.0, 4.8, ['Fn을 받는 함수에 값을 바꾸는 클로저를 넘기면 컴파일 오류 · FnMut로 받으라고 알려 줘요', 'passing a mutating closure where Fn is required fails, and the hint says accept FnMut'], 'w', 2, { w: 12.4 });
      mono(S, 'e2', 19.0, 6.2, ['error[E0382]: use of moved value: `eat`', 'closure cannot be invoked more than once'], 3, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l3', 19.0, 7.4, ['FnOnce는 캡처한 값을 소비해서 한 번만 부를 수 있어요', 'an FnOnce consumes what it captured, so it can be called only once'], 'r', 3, { w: 12.4 });
      T(S, 'sz', 19.0, 8.8, 'size_of: none 0, &name 8, String 24, i32 4', 'cz-mono rsx-tiny rsx-g', 4, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.4, ['클로저는 캡처만 담은 익명 구조체 · Box<dyn Fn>은 16B 팻 포인터예요', 'a closure is an anonymous struct of its captures; Box<dyn Fn> is a 16 B fat pointer'], 'g', 4, { w: 12.4 });
      lbl(S, 'm4', 1, 8.1, ['impl Fn으로 받으면 호출이 인라인되고, dyn Fn은 가상 호출 대신 여러 클로저를 한 타입으로 담아요', 'taking impl Fn lets calls inline, while dyn Fn stores different closures as one type via virtual calls'], 'a', 4, { w: 16.0 });
    },
    notes: [['클로저가 캡처한 변수를 어떻게 쓰는지에 따라 세 트레이트 중 하나가 정해져요 · 읽기만 하면 &T로 빌려 Fn, 값을 바꾸면 &mut T로 빌려 FnMut, 값을 소비하면 FnOnce예요 · 함수는 받을 클로저의 종류를 이 트레이트로 적어요', 'how a closure uses its captured variables decides which of three traits it implements: reading borrows &T for Fn, mutating borrows &mut T for FnMut, and consuming a value makes it FnOnce, and functions state which kind they accept with these traits'], ['Fn을 받는 함수에 n += 1처럼 값을 바꾸는 클로저를 넘기자 이 환경에서 E0594 cannot assign to `n`, as it is a captured variable in a `Fn` closure가 났어요 · 컴파일러는 매개변수를 FnMut로 바꾸라고 알려 줘요 · 여러 스레드에서 함께 불릴 수 있는지도 이 구분으로 보장돼요', 'passing a mutating closure such as n += 1 to a function that takes Fn produced E0594 cannot assign to `n`, as it is a captured variable in a `Fn` closure here, and the compiler suggests changing the parameter to FnMut; the same distinction guarantees whether a closure can be called from several threads'], ['move || drop(name)은 name의 소유권을 가져가 호출할 때 소비하므로 FnOnce예요 · 두 번 부르자 E0382 use of moved value: `eat`와 함께 closure cannot be invoked more than once라는 설명이 나왔어요 · move는 캡처 방식만 바꾸고, 어떤 트레이트인지는 본문이 정해요', 'move || drop(name) takes ownership of name and consumes it when called, so it is FnOnce: calling it twice produced E0382 use of moved value: `eat` with the explanation closure cannot be invoked more than once; move only changes how variables are captured, while the body decides the trait'], ['클로저는 캡처한 값만 필드로 가진 익명 구조체예요 · 이 환경에서 캡처가 없으면 0바이트, &name 하나면 8바이트, String을 move하면 24바이트, i32를 move한 adder는 4바이트였고, Box<dyn Fn>은 데이터와 vtable을 가리키는 16바이트 팻 포인터였어요', 'a closure is an anonymous struct whose fields are only its captures: here one with no captures was 0 bytes, one capturing &name 8 bytes, one moving a String 24 bytes, and the adder moving an i32 4 bytes, while a Box<dyn Fn> was a 16-byte fat pointer to the data and a vtable']],
    fin: [['Fn, FnMut, FnOnce는 캡처를 쓰는 방식', 'Fn, FnMut and FnOnce describe how captures are used', 'rsx-xs rsx-a'], ['클로저 = 캡처만 담은 구조체', 'a closure is a struct of its captures'], ['impl Fn은 인라인, dyn Fn은 가상 호출', 'impl Fn inlines, dyn Fn calls virtually']],
    caps: [['세 가지 클로저 트레이트', 'Three closure traits'], ['FnMut', 'FnMut'], ['FnOnce', 'FnOnce'], ['클로저의 크기', 'The size of a closure'], ['클로저', 'Closures']]
  });
}

function sErrors() {
  return CW('rs-errors', {
    code: ['#[derive(Debug, thiserror::Error)]', 'enum ConfigError {', '  #[error("bad port: {0}")]', '  BadPort(#[from] ParseIntError), }', 'let t = fs::read_to_string(p)', '    .with_context(|| format!("reading {p}"))?;'],
    hl: [[0, 3, 'accent'], [3, 1, 'warn'], [4, 2, 'ok'], [0, 6]],
    draw: (S) => {
      mono(S, 'mo', 19.0, .5, ['missing key `port`', 'bad port: invalid digit found in string'], 1, { w: 12.4, dy: .55, c: 'rsx-g' });
      lbl(S, 'l1', 19.0, 1.8, ['thiserror는 #[error] 문구로 Display와 Error 구현을 만들어 줘요 · 주로 라이브러리에서', 'thiserror derives Display and Error from the #[error] text, typically in libraries'], 'a', 1, { w: 12.4 });
      flow(S, 'cv', [['ParseIntError', 'warn', 19.0, 4.4], ['From', 'accent', 23.85, 2.6], ['BadPort', 'ok', 26.9, 4.5]], 3.3, 2);
      lbl(S, 'l2', 19.0, 4.5, ['#[from]이 From을 구현해서 ?가 오류를 BadPort로 바꿔 줘요 · 호출자는 match로 구별해요', '#[from] implements From, so ? converts the error into BadPort, and callers can match on it'], 'w', 2, { w: 12.4 });
      mono(S, 'ah', 19.0, 5.9, nbs(['Error: reading config.toml', 'Caused by:', '    No such file or directory (os error 2)']), 3, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l3', 19.0, 7.7, ['anyhow는 어떤 오류든 담는 8B 상자 · context가 원인 위에 설명을 쌓아요 (이 환경의 출력)', 'anyhow::Error is an 8 B box for any error; context stacks a message on the cause'], 'r', 3, { w: 12.4 });
      T(S, 'lb', 19.0, 9.2, 'library → thiserror · app → anyhow', 'cz-mono rsx-tiny rsx-a', 4, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.8, ['호출자가 종류를 구별해야 하면 enum, 보여 주기만 하면 anyhow', 'use an enum when callers must tell errors apart, anyhow when they only report'], 'g', 4, { w: 12.4 });
      lbl(S, 'm3', 1, 8.1, ['main이 anyhow::Result를 돌려주면 Err일 때 이 메시지를 찍고 종료 코드 1로 끝나요', 'when main returns anyhow::Result, an Err prints this message and exits with code 1'], 'r', 3, { w: 16.0 });
    },
    notes: [['라이브러리는 호출자가 실패의 종류를 구별할 수 있게 오류를 enum으로 정의하는 경우가 많아요 · thiserror 크레이트의 derive는 #[error("…")] 문구로 Display를 만들고 std::error::Error 트레이트를 구현해 줘요 · 이 환경에서 missing key `port`, bad port: invalid digit found in string처럼 찍혔어요', 'libraries often define their errors as an enum so callers can tell failures apart, and the thiserror crate’s derive builds Display from the #[error("…")] text and implements the std::error::Error trait, printing here as missing key `port` and bad port: invalid digit found in string'], ['#[from]을 붙이면 ParseIntError에서 ConfigError로 바꾸는 From 구현이 생겨요 · ? 연산자는 Err를 돌려줄 때 From으로 변환하므로, s.parse()?만 써도 BadPort가 돼요 · 호출자는 match로 Err(ConfigError::BadPort(e))를 골라 처리했어요', 'adding #[from] generates a From implementation converting ParseIntError into ConfigError, and since the ? operator converts through From when returning an Err, writing just s.parse()? yields BadPort, which the caller picked out with match on Err(ConfigError::BadPort(e))'], ['애플리케이션은 오류의 종류보다 무슨 일을 하다 실패했는지가 중요해요 · anyhow::Error는 어떤 오류든 담는 8바이트 포인터이고, with_context가 원인 위에 설명을 덧붙여요 · 없는 파일을 읽자 Error: reading config.toml과 Caused by: No such file or directory (os error 2)가 찍혔어요', 'applications care less about the kind of error than about what was being done when it failed: anyhow::Error is an 8-byte pointer holding any error, and with_context adds a message on top of the cause, so reading a missing file printed Error: reading config.toml followed by Caused by: No such file or directory (os error 2)'], ['기준은 호출자예요 · 호출자가 실패 종류에 따라 다르게 행동해야 하면 thiserror로 만든 enum을, 로그에 남기거나 사용자에게 보여 주기만 하면 anyhow를 써요 · 그래서 라이브러리는 thiserror, 실행 파일은 anyhow를 쓰는 조합이 흔해요', 'the deciding factor is the caller: when callers must act differently by kind of failure, use an enum built with thiserror, and when they only log or display it, use anyhow, which is why libraries with thiserror and executables with anyhow is a common combination']],
    fin: [['?는 From으로 오류를 변환해요', '? converts errors through From', 'rsx-xs rsx-a'], ['구별할 오류는 enum + thiserror', 'errors to tell apart: enum plus thiserror'], ['보고할 오류는 anyhow + context', 'errors to report: anyhow plus context']],
    caps: [['thiserror', 'thiserror'], ['#[from]과 ?', '#[from] and ?'], ['anyhow와 context', 'anyhow and context'], ['라이브러리와 앱', 'Libraries and apps'], ['실전 오류 처리', 'Error handling in practice']]
  });
}

function sPanicR() {
  return CW('rs-panic', {
    code: [['let _g = Guard;             // Drop 구현', 'let _g = Guard;             // impl Drop'], 'let v = vec![1, 2, 3];', 'v[black_box(10)];           // panic!', ['// 기본: 되감기 → Drop 실행, 코드 101', '// default: unwind → Drop runs, exit 101'], ['// panic = "abort" → 즉시 종료, 134', '// panic = "abort" → no Drop, exit 134']],
    hl: [[0, 3, 'accent'], [2, 1, 'danger'], [3, 1, 'warn'], [4, 1, 'danger']],
    draw: (S) => {
      chip(S, 'rs', 19.0, .5, 3.4, 'Result', 'ok', 1, { h: .8 }); chip(S, 'pn', 22.7, .5, 3.4, 'panic!', 'danger', 1, { h: .8 });
      lbl(S, 'l1', 19.0, 1.6, ['파일 없음, 잘못된 입력처럼 일어날 수 있는 일은 Result, 불변 조건이 깨진 버그는 panic', 'Result for what can happen, like a missing file; panic when an invariant breaks'], 'a', 1, { w: 12.4 });
      mono(S, 'pm', 19.0, 3.1, ['panicked at pa.rs:10:21:', 'index out of bounds: the len is 3', 'but the index is 10'], 2, { w: 12.4, dy: .55, c: 'rsx-r' });
      lbl(S, 'l2', 19.0, 4.9, ['범위 밖 인덱스는 C처럼 엉뚱한 메모리를 읽지 않고 panic · 위치도 알려 줘요', 'an out-of-bounds index panics instead of reading stray memory, and reports where'], 'r', 2, { w: 12.4 });
      flow(S, 'uw', [['panic', 'danger', 19.0, 2.6], [['되감기', 'unwind'], 'warn', 22.05, 3.0], ['Drop', 'ok', 25.5, 2.6], ['101', 'ink-3', 28.55, 2.85]], 6.3, 3);
      lbl(S, 'l3', 19.0, 7.5, ['기본은 스택을 되감으며 Drop을 실행해 자원을 정리 · 종료 코드 101 (이 환경)', 'by default the stack unwinds and Drop runs to clean up; exit code 101 here'], 'w', 3, { w: 12.4 });
      chip(S, 'ab', 19.0, 8.9, 5.8, 'abort → 134', 'danger', 4, { h: .8 });
      lbl(S, 'l4', 19.0, 9.9, ['abort는 되감기 없이 즉시 종료 · catch_unwind도, 정리도 없어요', 'abort exits at once without unwinding: no catch_unwind and no cleanup'], 'r', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['unwrap()과 expect()도 실패하면 panic이에요 · 라이브러리는 Result를 돌려줘요', 'unwrap() and expect() panic on failure too, so libraries return Result instead'], 'a', 1, { w: 16.0 });
    },
    notes: [['Rust는 실패를 두 가지로 나눠요 · 파일이 없거나 입력이 잘못된 것처럼 정상적으로 일어날 수 있는 실패는 Result로 돌려주고, 배열 범위를 넘거나 불변 조건이 깨진 것처럼 프로그램의 버그는 panic으로 멈춰요 · panic을 일반적인 흐름 제어에 쓰지는 않아요', 'Rust splits failures in two: failures that can happen in normal operation, such as a missing file or bad input, are returned as Result, while program bugs, such as indexing past an array or a broken invariant, stop with a panic, which is not used for ordinary control flow'], ['길이 3인 Vec에 인덱스 10으로 접근하자 C처럼 옆 메모리를 읽는 대신 index out of bounds: the len is 3 but the index is 10과 함께 파일과 줄 위치를 찍고 panic이 났어요 · 정의되지 않은 동작이 생기지 않아요', 'accessing a length-3 Vec at index 10 did not read neighboring memory as C would; it panicked, printing index out of bounds: the len is 3 but the index is 10 with the file and line, so no undefined behavior occurs'], ['기본 동작은 되감기예요 · panic이 나면 스택을 거꾸로 올라가며 각 변수의 Drop을 실행해 파일, 잠금, 메모리를 정리해요 · 이 환경에서도 drop guard가 찍힌 뒤 종료 코드 101로 끝났어요 · catch_unwind로 되감기를 잡을 수도 있어요', 'the default behavior is unwinding: a panic walks back up the stack running each variable’s Drop to clean up files, locks and memory, and here drop guard was printed before the process ended with exit code 101; catch_unwind can even catch the unwinding'], ['Cargo.toml에 panic = "abort"를 두면 되감지 않고 즉시 프로세스를 끝내요 · 이 환경에서 Drop이 실행되지 않고 SIGABRT로 종료 코드 134가 나왔어요 · 되감기 코드가 빠져 조금 작고 빠르지만 정리와 catch_unwind를 포기하는 선택이라, 임베디드나 크기에 민감한 곳에서 써요', 'setting panic = "abort" in Cargo.toml ends the process immediately without unwinding: here Drop did not run and it exited via SIGABRT with code 134, and dropping the unwinding code makes things slightly smaller and faster, but it gives up cleanup and catch_unwind, so it is chosen for embedded or size-sensitive targets']],
    fin: [['예상된 실패는 Result, 버그는 panic', 'expected failures are Results, bugs are panics', 'rsx-xs rsx-a'], ['되감기는 Drop을 실행해요', 'unwinding runs Drop'], ['abort는 즉시 종료', 'abort ends the process at once']],
    caps: [['Result와 panic', 'Result and panic'], ['범위 검사', 'Bounds checks'], ['되감기', 'Unwinding'], ['abort', 'abort'], ['panic', 'Panics']]
  });
}

function sPerfR() {
  return CW('rs-perf', {
    code: [['for i in 0..n { s += a[i] * b[i]; } // 검사?', 'for i in 0..n { s += a[i] * b[i]; } // checks?'], 'let mut out = Vec::with_capacity(n);', '[profile.release]', 'lto = true', 'codegen-units = 1', '$ RUSTFLAGS="-C target-cpu=native"'],
    hl: [[0, 1, 'accent'], [1, 1, 'warn'], [2, 3, 'ok'], [5, 1, 'ok']],
    draw: (S) => {
      rbars(S, 'b1', .5, [['a[i]', 4.0, 'accent', '16 ms'], ['zip', 4.0, 'ok', '16 ms']], 1);
      lbl(S, 'l1', 19.0, 1.7, ['경계 검사는 대개 거의 공짜 · LLVM이 길이를 한 번 확인하고 SIMD로 벡터화했어요 (2천만 원소)', 'bounds checks are nearly free: LLVM checked once, then vectorized (20M elements)'], 'a', 1, { w: 12.4 });
      rbars(S, 'b2', 3.2, [['new', 4.9, 'ink-3', '49 ms'], ['with_cap', 4.2, 'ok', '42 ms']], 2);
      lbl(S, 'l2', 19.0, 4.4, ['용량을 미리 잡으면 재할당과 복사가 사라져요 · 2천만 번 push', 'reserving capacity skips reallocation and copying (20M pushes)'], 'w', 2, { w: 12.4 });
      rbars(S, 'b3', 5.9, [['default', 5.0, 'ink-3', '456 KB'], ['lto+cgu1', 4.3, 'ok', '392 KB']], 3);
      lbl(S, 'l3', 19.0, 7.1, ['lto와 codegen-units = 1은 크레이트 경계를 넘어 최적화 · 대신 빌드가 느려져요', 'lto and codegen-units = 1 optimize across crates, at the cost of slower builds'], 'g', 3, { w: 12.4 });
      rbars(S, 'b4', 8.6, [['x86-64', 5.3, 'ink-3', '88 ms'], ['native', 1.6, 'ok', '26 ms']], 4);
      lbl(S, 'l4', 19.0, 9.8, ['target-cpu=native로 AVX2·AVX-512를 쓰자 3.4배 · 그 CPU 계열에서만 돌아요', 'target-cpu=native used AVX2/AVX-512: 3.4× faster, but runs only on such CPUs'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 8.1, ['고치기 전에 측정 · perf, cargo flamegraph, criterion으로 병목을 먼저 찾아요', 'measure before fixing: find the bottleneck first with perf, cargo flamegraph or criterion'], 'a', 1, { w: 16.0 });
    },
    notes: [['인덱스마다 경계 검사가 붙어도 대개 거의 공짜예요 · 이 환경에서 2천만 원소의 a[i] * b[i] 인덱스 루프와 zip 반복자가 모두 16ms였어요 · 어셈블리를 보니 LLVM이 길이를 루프 앞에서 한 번 확인하고 SIMD 명령으로 벡터화했어요 · 임의 인덱스로 읽는 경우도 검사 20ms, get_unchecked 20ms로 차이가 거의 없었어요', 'bounds checks on every index are usually nearly free: here an a[i] * b[i] index loop and a zip iterator over 20 million elements both took 16 ms, and the assembly showed LLVM checking the length once before the loop and vectorizing with SIMD instructions; even reads at random indices took 20 ms checked versus 20 ms with get_unchecked'], ['Vec::new()에서 시작해 push하면 용량이 찰 때마다 더 큰 버퍼를 할당해 원소를 복사해요 · 크기를 알면 Vec::with_capacity로 미리 잡아요 · 이 환경에서 2천만 번 push가 49ms에서 42ms로 줄었어요 · collect는 크기 힌트로 이 일을 알아서 해요', 'pushing onto a Vec started with Vec::new() allocates a bigger buffer and copies the elements each time capacity runs out, so a known size is reserved up front with Vec::with_capacity: here 20 million pushes went from 49 ms to 42 ms, and collect does this automatically using the size hint'], ['release 프로필은 더 조일 수 있어요 · lto = true는 링크할 때 크레이트 경계를 넘어 인라인과 최적화를 하고, codegen-units = 1은 크레이트를 한 덩어리로 최적화해요 · 이 환경에서 실행 파일이 456KB에서 392KB로 줄었고, strip과 panic = "abort"까지 더하면 318KB였어요 · 대신 빌드가 느려져요', 'the release profile can be tightened further: lto = true inlines and optimizes across crate boundaries at link time, and codegen-units = 1 optimizes each crate as a single unit, which shrank the executable here from 456 KB to 392 KB, and to 318 KB with strip and panic = "abort" added, at the cost of slower builds'], ['기본 빌드는 모든 x86-64 CPU에서 돌도록 오래된 SSE2 명령만 써요 · -C target-cpu=native로 이 CPU의 AVX2와 AVX-512를 허용하자, 캐시에 들어가는 곱셈 합 계산이 88ms에서 26ms로 3.4배 빨라졌어요 · 대신 그 기능이 없는 CPU에서는 실행되지 않아 배포용 빌드에는 조심해서 써요', 'the default build uses only the older SSE2 instructions so it runs on every x86-64 CPU, and allowing this CPU’s AVX2 and AVX-512 with -C target-cpu=native made a cache-resident multiply-sum go from 88 ms to 26 ms, 3.4× faster, but the binary will not run on CPUs lacking those features, so it is used with care for distributed builds']],
    fin: [['측정 먼저, 그리고 --release', 'measure first, and with --release', 'rsx-xs rsx-a'], ['경계 검사보다 할당과 캐시가 먼저', 'allocation and cache matter before bounds checks'], ['lto와 target-cpu는 대가를 알고 써요', 'use lto and target-cpu knowing the trade-offs']],
    caps: [['경계 검사', 'Bounds checks'], ['미리 할당', 'Preallocation'], ['release 프로필', 'The release profile'], ['target-cpu', 'target-cpu'], ['성능 다루기', 'Tuning performance']]
  });
}
return { css: CSSX + CSSY, secs: [
  sec('rs-own', '소유권과 빌림', 'Ownership and borrowing', 'GC 없이 메모리를 안전하게', 'Memory safety without a GC', '값마다 하나뿐인 주인과 이동, 공유 XOR 변경이라는 빌림 규칙, 수명, Copy와 Clone, 자동 정리 Drop, 그리고 String과 슬라이스를 이 환경의 Rust 1.97 컴파일러가 실제로 낸 오류와 함께 봐요.', 'One owner per value and moves, the aliasing-XOR-mutation borrowing rule, lifetimes, Copy and Clone, automatic cleanup with Drop, and String and slices, with the actual errors from this environment’s Rust 1.97 compiler.', [
    item('rs-ownership', '소유권과 이동', 'Ownership and moves',
      'Rust의 모든 값에는 주인이 하나뿐이고, 대입과 함수 전달은 소유권을 옮겨요. 이동된 값은 컴파일러가 쓰지 못하게 막고, 주인이 사라지면 자동으로 해제돼요.',
      'Rust는 가비지 컬렉터 없이도, C처럼 손으로 free를 부르지 않고도 메모리를 안전하게 관리해요. 그 바탕이 소유권 규칙이에요. 첫째, 모든 값에는 주인(owner)인 변수가 있어요. 둘째, 주인은 한 번에 하나뿐이에요. 셋째, 주인이 범위를 벗어나면 값이 해제돼요. let s = String::from("hi")는 힙에 두 바이트를 할당하고, 스택의 s에는 포인터, 길이, 용량으로 된 24바이트 헤더가 놓여 s가 버퍼의 주인이 돼요. let t = s는 이 헤더 24바이트만 t로 복사하고 s를 더 이상 쓸 수 없게 만들어요. 이것이 이동(move)이에요. 힙 버퍼는 복사되지 않으니 빠르고, 주인이 여전히 하나라서 s와 t가 같은 버퍼를 두 번 해제하는 이중 해제가 원천적으로 불가능해요. C++의 std::move와 달리 Rust에서는 이동이 기본 동작이고, 이동된 변수는 비어 있는 상태로 남는 게 아니라 아예 쓸 수 없어요. 이 환경에서 이동한 뒤 s를 출력하려 하자 error[E0382]: borrow of moved value: `s`와 함께 이동이 일어난 줄과 사용된 줄을 짚어 주며 컴파일이 실패했어요. 함수 인자로 넘기는 것도 이동이라, take(t)를 부른 뒤에는 t를 쓸 수 없고, 값은 take의 매개변수가 범위를 벗어나는 함수 끝에서 해제돼요. 값을 돌려받으려면 함수가 반환해 소유권을 다시 넘기거나, 다음 장의 빌림을 써요. 이 모든 검사는 컴파일 때 끝나서 실행 중에는 아무 비용이 없고, 해제 시점이 코드 구조로 정해지므로 GC처럼 언제 멈출지 모르는 일도 없어요.',
      'Every Rust value has exactly one owner, and assignment and passing to functions move ownership. The compiler forbids using moved values, and values are freed automatically when their owner goes away.',
      'Rust manages memory safely without a garbage collector and without calling free by hand as in C. Underneath are the ownership rules. First, every value has an owner variable. Second, there is only one owner at a time. Third, when the owner leaves scope, the value is freed. let s = String::from("hi") allocates two bytes on the heap, and s on the stack holds a 24-byte header of pointer, length and capacity, making s the buffer’s owner. let t = s copies just this 24-byte header into t and makes s unusable. This is a move. The heap buffer is not copied, so it is fast, and since there is still only one owner, a double free in which s and t free the same buffer is impossible by construction. Unlike C++’s std::move, moving is Rust’s default behavior, and a moved variable is not left in some empty state but cannot be used at all. Here, trying to print s after the move failed to compile with error[E0382]: borrow of moved value: `s`, pointing out the line where the move happened and the line where s was used. Passing a function argument is also a move, so t cannot be used after calling take(t), and the value is freed at the end of take, when its parameter leaves scope. To get a value back, the function returns it, handing ownership back, or the code uses the borrowing described next. All these checks finish at compile time and cost nothing at run time, and because the freeing point is fixed by the structure of the code, there are no unpredictable pauses as with a GC.', sOwnership()),
    item('rs-borrow', '빌림 규칙', 'The borrowing rules',
      '빌림은 소유권을 넘기지 않고 값을 쓰는 참조예요. 공유 참조 &T는 여럿, 가변 참조 &mut T는 하나만 허용해서 댕글링과 데이터 경쟁을 컴파일 때 막아요.',
      '매번 소유권을 넘기고 돌려받으면 불편하니, Rust는 값을 잠시 빌려 쓰는 참조를 제공해요. 참조에는 두 종류가 있어요. 공유 참조 &T는 값을 읽기만 하는 참조로, 동시에 여러 개를 만들 수 있어요. 가변 참조 &mut T는 값을 바꿀 수 있는 참조로, 한 번에 딱 하나만 있을 수 있고 그동안에는 다른 공유 참조도 있으면 안 돼요. 즉 여럿이 함께 보거나 하나가 바꾸거나 둘 중 하나만 허용하는 규칙이라서 "공유 XOR 변경(aliasing XOR mutation)"이라고 불러요. 이 단순한 규칙이 여러 종류의 버그를 한꺼번에 막아요. let first = &v[0]으로 벡터의 첫 원소를 빌린 채 v.push(4)를 부르면, push는 용량이 모자랄 때 버퍼를 재할당하므로 first가 해제된 메모리를 가리키게 될 수 있어요. C++에서는 반복자 무효화로 실행 중에 조용히 메모리를 망가뜨리는 버그지만, Rust는 이 환경에서처럼 error[E0502]: cannot borrow `v` as mutable because it is also borrowed as immutable로 컴파일 단계에서 막아요. 가변 참조를 두 개 만들면 E0499가 나요. 빌림은 선언된 블록 끝이 아니라 마지막으로 쓰이는 지점까지만 유효해요(비어휘적 수명, NLL). 그래서 println!("{first}")를 push 앞으로 옮기면 그대로 컴파일돼요. 같은 규칙이 스레드에도 적용되어, 두 스레드가 같은 데이터를 동시에 바꾸는 데이터 경쟁은 안전한 Rust에서 컴파일되지 않아요. 이런 검사를 하는 컴파일러의 부분을 빌림 검사기(borrow checker)라고 하고, 모두 컴파일 때 끝나서 실행 비용은 없어요. 처음에는 빌림 검사기와 싸우는 느낌이 들지만, 오류 메시지가 문제 지점을 정확히 짚어 줘요.',
      'Borrowing uses a value through a reference without taking ownership. Many shared &T or a single &mut T are allowed, which stops dangling references and data races at compile time.',
      'Handing ownership over and back every time would be tedious, so Rust offers references that borrow a value for a while. There are two kinds. A shared reference &T only reads the value, and many can exist at once. A mutable reference &mut T can change the value, and only one may exist at a time, with no shared references alongside it. The rule allows either many readers together or one writer, never both, which is why it is called aliasing XOR mutation. This simple rule stops several kinds of bugs at once. If a vector’s first element is borrowed with let first = &v[0] and then v.push(4) is called, push may reallocate the buffer when capacity runs out, leaving first pointing at freed memory. In C++ that is iterator invalidation, a bug that silently corrupts memory at run time, but Rust stops it at compile time, as it did here with error[E0502]: cannot borrow `v` as mutable because it is also borrowed as immutable. Creating two mutable references gives E0499. A borrow is valid only until its last use, not to the end of the block where it was declared (non-lexical lifetimes, NLL), so moving println!("{first}") before the push compiles as is. The same rule applies to threads, so data races, in which two threads change the same data at once, do not compile in safe Rust. The part of the compiler doing these checks is called the borrow checker, and since everything finishes at compile time, there is no run-time cost. At first it can feel like fighting the borrow checker, but its error messages pinpoint exactly where the problem is.', sBorrow()),
    item('rs-lifetime', '수명', 'Lifetimes',
      '수명은 참조가 유효한 구간이에요. 컴파일러는 참조가 가리키는 값보다 오래 쓰이지 않는지 확인하고, 애매할 때만 \'a 같은 표기로 관계를 알려 줘요.',
      '수명(lifetime)은 참조가 유효한 코드 구간이에요. 빌림 검사기는 모든 참조가 그것이 가리키는 값보다 오래 쓰이지 않는지 확인해서 댕글링 참조를 막아요. 내부 블록에서 let x = 5를 만들고 r = &x로 빌린 뒤 블록 밖에서 r을 쓰면, x는 블록 끝에서 해제되는데 r은 그 뒤에도 쓰여요. 이 환경에서 이 코드는 error[E0597]: `x` does not live long enough와 함께 x가 해제되는 지점과 r이 나중에 쓰이는 지점을 보여 주며 컴파일되지 않았어요. 대부분의 경우 컴파일러가 수명을 스스로 추론하지만, 함수가 참조를 여러 개 받아 참조를 돌려줄 때는 결과가 어느 입력을 빌렸는지 시그니처만으로는 알 수 없어요. fn longest(a: &str, b: &str) -> &str는 a와 b 중 더 긴 것을 돌려주는데, 호출하는 쪽은 결과를 언제까지 써도 되는지 알아야 하므로 E0106 missing lifetime specifier 오류가 나요. 이럴 때 fn longest<\'a>(a: &\'a str, b: &\'a str) -> &\'a str처럼 수명 매개변수를 적어요. 이 표기는 세 참조가 같은 수명 \'a를 공유한다는 관계를 말할 뿐이고, 실제로 \'a는 a와 b가 모두 살아 있는 구간, 즉 더 짧은 쪽이 되어서 결과도 그 안에서만 쓸 수 있어요. 수명 표기는 값의 수명을 늘리거나 바꾸지 않고, 컴파일러가 검사할 수 있도록 관계를 설명할 뿐이며, 실행 코드에는 아무것도 더하지 않아요. 생략 규칙(elision) 덕분에 대부분의 함수는 표기가 필요 없어요. 입력 참조가 하나면 출력이 그 수명을 받고, &self를 받는 메서드면 출력이 self의 수명을 받아요. 문자열 리터럴은 실행 파일에 들어 있어 프로그램 내내 살아 있으므로 타입이 &\'static str이에요. 구조체에 참조를 담을 때도 struct Parser<\'a> { input: &\'a str }처럼 수명을 적어서, 구조체가 빌린 데이터보다 오래 살지 못하게 해요.',
      'A lifetime is the span in which a reference is valid. The compiler checks that no reference outlives its value, and only in ambiguous cases do annotations such as \'a state the relationship.',
      'A lifetime is the stretch of code in which a reference is valid. The borrow checker prevents dangling references by checking that no reference is used longer than the value it points to. Create let x = 5 in an inner block, borrow it with r = &x, and use r outside the block, and x is freed at the block’s end while r is still used afterward. Here that code failed to compile with error[E0597]: `x` does not live long enough, showing where x is dropped and where r is later used. Most of the time the compiler infers lifetimes itself, but when a function takes several references and returns one, its signature alone does not say which input the result borrows. fn longest(a: &str, b: &str) -> &str returns the longer of a and b, and since callers need to know how long the result may be used, it fails with E0106 missing lifetime specifier. In such cases a lifetime parameter is written, as in fn longest<\'a>(a: &\'a str, b: &\'a str) -> &\'a str. The annotation only states that the three references share one lifetime \'a; in practice \'a becomes the span where both a and b are alive, the shorter of the two, so the result can be used only within it. Lifetime annotations neither extend nor change how long values live; they describe relationships so the compiler can check them, and they add nothing to the generated code. Thanks to the elision rules, most functions need no annotations: with a single input reference the output takes its lifetime, and for methods taking &self the output takes self’s. String literals live inside the executable for the whole program, so their type is &\'static str. A struct holding a reference also states a lifetime, as in struct Parser<\'a> { input: &\'a str }, so the struct cannot outlive the data it borrows.', sLifetime()),
    item('rs-copy', 'Copy와 Clone', 'Copy and Clone',
      '정수 같은 단순한 Copy 타입은 대입하면 비트가 복사되고, 자원을 가진 타입은 이동해요. 깊은 복사는 clone을 명시적으로 불러서 비용이 코드에 드러나요.',
      '모든 대입이 이동인 것은 아니에요. i32, u8, f64, bool, char, 그리고 공유 참조 &T처럼 스택에만 있는 단순한 타입은 Copy 트레이트를 구현해요. let x = 5; let y = x는 비트를 그대로 복사하므로 x와 y를 모두 계속 쓸 수 있어요. 이런 타입은 복사가 싸고 해제할 자원도 없어서 이동으로 막을 이유가 없기 때문이에요. 반면 String처럼 힙 자원을 가진 값은 대입하면 이동해요. 같은 내용의 독립된 값이 정말 필요하면 s.clone()을 명시적으로 불러요. clone은 새 힙 버퍼를 할당하고 내용을 복사하는 깊은 복사예요. Rust는 이렇게 비싼 복사를 반드시 코드에 드러나게 해서, 성능 문제가 숨지 않게 해요. 코드에 clone이 너무 많다면 빌림으로 바꿀 수 있는지 살펴볼 신호예요. 직접 만든 타입도 #[derive(Clone, Copy)]로 Copy가 될 수 있어요. f64 두 개로 된 점 구조체 P는 16바이트라 Copy로 만들면 대입이 memcpy 한 번과 같아요. Copy는 Clone을 상위 트레이트로 요구해서 둘을 함께 derive해요. 하지만 모든 필드가 Copy여야 하고, String, Vec, Box처럼 자원을 소유하거나 Drop을 구현한 타입은 Copy가 될 수 없어요. 비트만 복사하면 두 값이 같은 힙 버퍼를 가리키고 둘 다 해제하려 할 것이기 때문이에요. 이 제약은 컴파일러가 강제해서, Drop을 구현한 타입에 Copy를 derive하면 컴파일 오류가 나요. 정리하면 Copy는 암묵적이고 항상 싼 비트 복사이고, Clone은 명시적이며 비쌀 수 있는 복제예요. Rc나 Arc의 clone은 예외적으로 데이터를 복사하지 않고 참조 수만 늘리는 얕은 복제예요.',
      'Simple Copy types such as integers are copied bit for bit on assignment, while types that own resources move. Deep copies require an explicit clone, so their cost shows in the code.',
      'Not every assignment is a move. Simple stack-only types such as i32, u8, f64, bool, char and the shared reference &T implement the Copy trait. let x = 5; let y = x copies the bits as they are, so both x and y remain usable. Such types are cheap to copy and own no resources to free, so there is no reason to restrict them with moves. Values that own heap resources, such as a String, move on assignment instead. When an independent value with the same contents is truly needed, call s.clone() explicitly. clone is a deep copy that allocates a new heap buffer and copies the contents. Rust insists that expensive copies like this appear in the code, so performance problems cannot hide; too many clones in code are a signal to check whether borrowing would do. Your own types can become Copy with #[derive(Clone, Copy)] too. A point struct P made of two f64 values is 16 bytes, and making it Copy turns assignment into a single memcpy. Copy requires Clone as a supertrait, so the two are derived together. But every field must be Copy, and types that own resources or implement Drop, such as String, Vec and Box, can never be Copy, because copying just the bits would leave two values pointing at the same heap buffer, both trying to free it. The compiler enforces this, so deriving Copy on a type that implements Drop is a compile error. In short, Copy is an implicit and always cheap bit copy, while Clone is an explicit and possibly expensive duplicate. The clone of Rc or Arc is an exception: a shallow clone that copies no data and only increments a reference count.', sCopy()),
    item('rs-drop', 'Drop과 해제 순서', 'Drop and destruction order',
      'Drop 트레이트는 소멸자예요. 주인이 범위를 벗어나면 컴파일러가 drop 호출을 넣고, 지역 변수는 선언의 역순으로 해제돼요.',
      'Rust에서 값이 해제될 때 할 일은 Drop 트레이트의 drop 메서드에 적어요. C++의 소멸자에 해당하고, 파일 닫기, 소켓 정리, 락 풀기 같은 자원 정리를 맡아요. 값의 주인이 범위를 벗어나면 컴파일러가 그 자리에 drop 호출을 자동으로 넣으므로, 정리 코드를 잊어버릴 수 없어요. 이것이 Rust식 RAII예요. 해제 시점은 코드의 구조로 정확히 정해져요. 이 환경에서 drop할 때 이름을 출력하는 N 타입으로 실험했어요. take(N("c"))로 c를 함수에 넘기면 소유권이 take로 이동해서, c는 take가 끝나는 순간 해제되어 took c 바로 뒤에 drop c가 찍혔어요. { let _d = N("d"); }처럼 블록 안에서 만든 d는 블록의 닫는 중괄호에서 해제되어 drop d가 그다음에 나왔어요. main 끝에서는 남은 지역 변수가 선언의 역순으로 해제되어, 나중에 선언한 b가 먼저, a가 나중에 drop됐어요. 역순인 이유는 나중에 만든 값이 먼저 만든 값을 참조하고 있을 수 있기 때문이에요. 구조체의 필드는 선언 순서대로 해제돼요. 값을 범위 끝보다 일찍 해제하고 싶으면 std::mem::drop(x)를 불러요. 이 함수는 값을 받아서 아무것도 하지 않는데, 소유권이 넘어왔다가 함수가 끝나며 해제되는 원리를 그대로 이용해요. 반대로 std::mem::forget은 값을 drop하지 않고 버려요. Drop은 메모리 안전을 지키지만 누수까지 막지는 않아요. 참조 수를 세는 Rc 두 개가 서로를 가리키면 수가 0이 되지 않아 영원히 drop되지 않으므로, 역방향 참조는 Weak로 만들어요. panic이 나서 스택이 되감길 때도 각 값의 drop이 불려서 자원이 정리돼요.',
      'The Drop trait is the destructor. The compiler inserts a drop call when the owner leaves scope, and locals are dropped in reverse order of declaration.',
      'In Rust, what should happen when a value is freed goes in the drop method of the Drop trait. It corresponds to a C++ destructor and handles cleanup such as closing files, tidying up sockets and releasing locks. When a value’s owner leaves scope, the compiler automatically inserts a call to drop right there, so cleanup code cannot be forgotten. This is Rust’s version of RAII. The moment of destruction is fixed precisely by the structure of the code. Here we experimented with a type N that prints its name when dropped. Passing c to a function with take(N("c")) moves ownership into take, so c is dropped the moment take returns, and drop c was printed right after took c. d, created inside a block as in { let _d = N("d"); }, is dropped at the block’s closing brace, so drop d came next. At the end of main, the remaining locals are dropped in reverse order of declaration, so b, declared later, dropped first and a after it. The order is reversed because a value created later may refer to one created earlier. Struct fields are dropped in declaration order. To free a value before the end of its scope, call std::mem::drop(x). The function takes the value and does nothing, relying on the very principle that ownership moves in and the value is freed when the function ends. Conversely, std::mem::forget discards a value without dropping it. Drop preserves memory safety, but it does not prevent leaks. If two reference-counted Rcs point at each other, their counts never reach zero and they are never dropped, so back references are made with Weak. When a panic unwinds the stack, each value’s drop is still called, so resources are cleaned up.', sDrop()),
    item('rs-slice', 'String과 슬라이스', 'Strings and slices',
      'String은 힙의 UTF-8 바이트를 소유하고, &str과 &[T]는 포인터와 길이로 된 16바이트 빌림이에요. 슬라이스는 글자 경계에서만 자를 수 있어요.',
      'Rust에는 문자열 타입이 두 가지 있어요. String은 힙에 있는 UTF-8 바이트를 소유하는 타입으로, 스택에 포인터, 길이, 용량으로 된 24바이트를 가지고 내용을 늘리거나 바꿀 수 있어요. &str은 어딘가에 있는 UTF-8 바이트를 빌린 문자열 슬라이스로, 시작 포인터와 길이만 가진 16바이트 팻 포인터예요. String::from("héllo")에서 é는 UTF-8로 0xc3 0xa9 두 바이트라서, 글자는 5개지만 len()은 바이트 수인 6이에요. let w = &s[0..3]은 바이트 0부터 3 앞까지를 가리키는 &str을 만들어서 복사 없이 "hé"를 얻어요. 슬라이스는 빌림이므로, w가 살아 있는 동안 s를 바꾸거나 이동할 수 없어요. 슬라이스의 경계는 바이트 위치라서 글자 중간을 자르면 안 돼요. &s[0..2]는 é의 두 바이트 사이를 자르려 하므로, 이 환경에서 end byte index 2 is not a char boundary; it is inside \'é\' (bytes 1..3 of string)라는 panic이 났어요. 글자 단위로 다루려면 s.chars()로 유니코드 스칼라 값(char, 4바이트)을 하나씩 꺼내고, 글자 수는 s.chars().count()로 세요. 그래서 Rust는 s[0]처럼 정수 하나로 문자열을 인덱싱하는 것을 아예 허용하지 않아요. 함수가 문자열을 읽기만 한다면 매개변수를 &String이 아니라 &str로 받는 것이 관례예요. &String은 역참조 강제 변환으로 &str로 바뀌어 넘어오고, 문자열 리터럴도 &\'static str이라 그대로 넘길 수 있기 때문이에요. 같은 원리로 배열과 Vec의 일부는 &[T] 슬라이스로 다뤄요. &a[1..3]은 배열의 1번과 2번 원소를 가리키는 포인터와 길이 2이고, 범위를 벗어나면 panic이 나요. 슬라이스 덕분에 함수는 데이터를 복사하지 않고 원하는 부분만 빌려서 처리할 수 있어요.',
      'A String owns UTF-8 bytes on the heap, while &str and &[T] are 16-byte borrows of a pointer and a length. Slices may only be cut at character boundaries.',
      'Rust has two string types. String owns UTF-8 bytes on the heap, holding 24 bytes of pointer, length and capacity on the stack, and its contents can grow and change. &str is a string slice borrowing UTF-8 bytes that live somewhere else, a 16-byte fat pointer of just a start pointer and length. In String::from("héllo"), é is two bytes in UTF-8, 0xc3 0xa9, so there are 5 characters but len() is the byte count, 6. let w = &s[0..3] makes a &str pointing at bytes 0 up to 3, getting "hé" without copying. A slice is a borrow, so s cannot be changed or moved while w is alive. Slice bounds are byte positions and must not split a character. &s[0..2] tries to cut between é’s two bytes, and here it panicked with end byte index 2 is not a char boundary; it is inside \'é\' (bytes 1..3 of string). To work by character, take Unicode scalar values (char, 4 bytes) one at a time with s.chars(), and count characters with s.chars().count(). That is why Rust does not allow indexing a string with a single integer, as in s[0], at all. When a function only reads a string, the convention is to take &str rather than &String, because a &String converts to &str through deref coercion and string literals, being &\'static str, can be passed as they are. By the same principle, parts of arrays and Vecs are handled as &[T] slices. &a[1..3] is a pointer to the array’s elements 1 and 2 with length 2, and going out of range panics. Thanks to slices, functions can borrow just the part they need and process it without copying data.', sSlice())
  ]),
  sec('rs-types', '타입과 트레이트', 'Types and traits', '표현력 있는 타입, 비용 없는 추상화', 'Expressive types, zero-cost abstractions', '데이터를 담는 열거형과 빠짐없는 match, null과 예외를 대신하는 Option과 Result, 트레이트와 정적 디스패치, vtable을 쓰는 트레이트 객체, 그리고 제네릭과 impl Trait를 이 환경에서 확인한 크기와 속도로 봐요.', 'Enums that carry data and exhaustive matches, Option and Result in place of null and exceptions, traits and static dispatch, trait objects with vtables, and generics and impl Trait, with sizes and speeds checked in this environment.', [
    item('rs-enum', '열거형과 패턴 매칭', 'Enums and pattern matching',
      'Rust의 enum은 변형마다 다른 데이터를 담는 태그 붙은 공용체예요. match는 모든 경우를 빠짐없이 다루도록 컴파일러가 강제해요.',
      'Rust의 enum은 C의 열거형처럼 이름 붙은 상수의 목록이 아니라, 여러 변형 중 하나를 그 변형의 데이터와 함께 담는 타입이에요. 이론에서는 합 타입(sum type), 구현에서는 태그 붙은 공용체라고 불러요. enum Shape { Circle(f64), Rect(f64, f64) }의 값은 Circle이면 반지름 하나, Rect면 너비와 높이를 가져요. 메모리에는 어느 변형인지 나타내는 태그와 가장 큰 변형의 데이터를 담을 공간이 놓여서, 이 환경에서 Shape는 8바이트 태그와 16바이트 데이터로 24바이트였어요. 값을 쓸 때는 match로 변형마다 분기해요. Shape::Rect(w, h) => w * h처럼 패턴이 변형을 확인하면서 안의 데이터를 꺼내 이름에 묶어 주고, match 전체가 값을 돌려주는 식이라 let a = match s { … }처럼 쓸 수 있어요. 컴파일러는 이를 태그에 따른 점프 테이블이나 비교로 만들어요. 가장 중요한 성질은 빠짐없음(exhaustiveness)이에요. match는 가능한 모든 경우를 다뤄야 해서, Shape에 Tri 변형을 추가하자 이 환경에서 error[E0004]: non-exhaustive patterns: `&Shape::Tri(_)` not covered로 컴파일이 실패했어요. 새 변형을 추가하면 처리를 빠뜨린 모든 곳이 컴파일 오류로 드러나므로, 상태 기계나 메시지 종류처럼 변형이 늘어나는 코드를 안전하게 고칠 수 있어요. 일부만 신경 쓸 때는 _ 와일드카드나 if let, 불리언으로 확인할 때는 matches! 매크로를 쓰고, 패턴 뒤에 if 가드를 붙여 조건을 더할 수 있어요. 컴파일러는 남는 비트 패턴을 태그로 재활용하는 니치 최적화도 해요. Box는 절대 null이 아니므로 Option<Box<T>>는 null을 None으로 써서 포인터와 같은 8바이트예요.',
      'A Rust enum is a tagged union whose variants carry different data. The compiler makes match handle every case.',
      'A Rust enum is not a list of named constants like a C enumeration but a type that holds one of several variants together with that variant’s data. In theory it is called a sum type, and in implementation a tagged union. A value of enum Shape { Circle(f64), Rect(f64, f64) } holds one radius if it is a Circle, or a width and a height if it is a Rect. In memory sit a tag saying which variant it is and room for the largest variant’s data, so here Shape was 24 bytes: an 8-byte tag plus 16 bytes of data. Values are used by branching on the variant with match. A pattern such as Shape::Rect(w, h) => w * h checks the variant while taking out its data and binding it to names, and since the whole match is an expression that yields a value, it can be written as let a = match s { … }. The compiler turns this into a jump table or comparisons on the tag. The most important property is exhaustiveness: a match must handle every possible case, so after adding a Tri variant to Shape, compilation failed here with error[E0004]: non-exhaustive patterns: `&Shape::Tri(_)` not covered. Adding a variant exposes every place that forgot to handle it as a compile error, so code whose variants grow, such as state machines or message kinds, can be changed safely. When only some cases matter, use the _ wildcard or if let; to test as a boolean use the matches! macro; and an if guard after a pattern adds a condition. The compiler also performs the niche optimization, reusing spare bit patterns as the tag. Since a Box is never null, Option<Box<T>> uses null as None and is the same 8 bytes as a pointer.', sEnum()),
    item('rs-option', 'Option과 Result', 'Option and Result',
      'Rust에는 null과 예외가 없어요. 없을 수 있는 값은 Option, 실패할 수 있는 연산은 Result로 표현하고, ? 연산자로 오류를 짧게 전파해요.',
      '토니 호어가 "10억 달러짜리 실수"라고 부른 null 참조가 Rust에는 없어요. 대신 값이 없을 수 있으면 표준 라이브러리의 enum Option<T> { Some(T), None }을 써요. Option<i32>는 그냥 i32와 다른 타입이라서, 값을 쓰려면 match나 if let으로 None인 경우를 반드시 처리해야 해요. 그래서 null 역참조 같은 오류가 컴파일 단계에서 사라져요. 니치 최적화 덕분에 Option<&T>나 Option<Box<T>>는 포인터와 같은 크기이고, Option<i32>는 이 환경에서 8바이트였어요. 실패할 수 있는 연산은 enum Result<T, E> { Ok(T), Err(E) }를 돌려줘요. 예외처럼 보이지 않게 위로 튀어 나가는 것이 아니라 반환값이라서, 함수 시그니처만 봐도 실패할 수 있는지 알 수 있어요. 이 환경에서 "8080".parse::<u16>()은 Ok(8080), "abc"는 invalid digit found in string, u16 범위를 넘는 "70000"은 number too large to fit in target type, 빈 문자열은 cannot parse integer from empty string 오류였어요. 오류를 호출자에게 넘길 때는 ? 연산자를 써요. let n = s.parse()?는 결과가 Ok면 값을 꺼내고, Err면 그 오류를 함수의 반환값으로 즉시 돌려줘요. 이때 From 트레이트로 오류 타입을 함수가 선언한 오류 타입으로 바꿔 주므로, 여러 종류의 오류를 한 타입으로 모을 수 있어요. Option에도 ?를 쓸 수 있어요. 두 타입에는 unwrap_or(0)처럼 기본값을 주거나, map, and_then, ok_or처럼 값을 변환하고 이어 붙이는 메서드가 많아요. unwrap()과 expect("메시지")는 None이나 Err이면 panic을 내서, 테스트나 절대 실패할 수 없음을 아는 곳에서만 쓰고 라이브러리 코드에서는 피해요. 애플리케이션에서는 anyhow, 라이브러리에서는 thiserror 크레이트로 오류 타입을 편하게 만드는 경우가 많아요.',
      'Rust has neither null nor exceptions. An absent value is an Option, a fallible operation returns a Result, and the ? operator propagates errors briefly.',
      'Rust has no null references, which Tony Hoare called his "billion-dollar mistake." Instead, a value that may be absent uses the standard library’s enum Option<T> { Some(T), None }. Option<i32> is a different type from plain i32, so using the value requires handling the None case with match or if let. Errors such as null dereferences thus vanish at compile time. Thanks to the niche optimization, Option<&T> and Option<Box<T>> are pointer-sized, and Option<i32> was 8 bytes here. Fallible operations return enum Result<T, E> { Ok(T), Err(E) }. Rather than flying invisibly upward like an exception, the error is a return value, so a function’s signature alone tells whether it can fail. Here "8080".parse::<u16>() gave Ok(8080), "abc" invalid digit found in string, "70000", beyond u16, number too large to fit in target type, and the empty string cannot parse integer from empty string. To pass an error on to the caller, use the ? operator. let n = s.parse()? takes out the value on Ok and, on Err, immediately returns that error from the function. It converts the error to the function’s declared error type through the From trait, so several kinds of error can be gathered into one type. ? works on Option too. Both types have many methods, such as unwrap_or(0) to supply a default and map, and_then and ok_or to transform and chain values. unwrap() and expect("message") panic on None or Err, so they are used only in tests or where failure is known to be impossible, and avoided in library code. Applications often use the anyhow crate and libraries the thiserror crate to build error types conveniently.', sOption()),
    item('rs-trait', '트레이트와 정적 디스패치', 'Traits and static dispatch',
      '트레이트는 타입이 구현할 동작의 약속이에요. 제네릭에 트레이트 경계를 걸면 컴파일러가 타입마다 코드를 만들어 직접 호출하고 인라인해요.',
      '트레이트는 여러 타입이 공통으로 가질 수 있는 동작을 정의해요. Java의 인터페이스와 비슷하지만 더 강력해요. trait Area { fn area(&self) -> f64; }는 area 메서드를 약속하고, 원 C와 사각형 R은 각자 impl Area for C처럼 구현해요. 트레이트는 기본 구현을 가진 메서드도 둘 수 있고, 이미 있는 타입에 나중에 구현할 수도 있어요. 다만 내 크레이트에 있는 트레이트나 타입 중 적어도 하나가 관련되어야 한다는 고아 규칙(orphan rule)이 있어서, 남의 트레이트를 남의 타입에 구현할 수는 없어요. 트레이트는 제네릭과 함께 쓰여요. fn total<T: Area>(xs: &[T])의 T: Area는 T가 Area를 구현한 타입이어야 한다는 트레이트 경계예요. total(&circles)처럼 호출하면 T가 C로 정해지므로, 컴파일러는 x.area()를 C::area의 직접 호출로 만들고 인라인까지 해서 손으로 쓴 코드와 같은 기계어를 만들어요. 이것을 정적 디스패치라고 해요. 이를 위해 컴파일러는 쓰인 타입마다 제네릭 함수를 따로 생성하는 단형화(monomorphization)를 해요. 이 환경에서 제네릭 함수 biggest를 i32 배열과 f64 배열에 쓰자 실행 파일 안에 biggest::<i32>와 biggest::<f64> 두 개의 함수가 생겼어요. C++ 템플릿과 같은 방식이라 추상화의 실행 비용이 0이지만, 쓰는 타입이 많으면 컴파일 시간과 바이너리 크기가 늘어요. 표준 라이브러리의 트레이트는 언어와 이어져 있어요. Display를 구현하면 {}로 출력되고, Iterator를 구현하면 for 문에서 쓸 수 있고, Add를 구현하면 + 연산자를 쓸 수 있어요. #[derive(Debug, Clone, PartialEq, Eq, Hash)]는 이런 흔한 트레이트의 구현을 자동으로 만들어 줘요.',
      'A trait is a promise of behavior that types implement. Putting trait bounds on generics lets the compiler generate code per type, calling directly and inlining.',
      'A trait defines behavior that several types can share. It resembles a Java interface but is more powerful. trait Area { fn area(&self) -> f64; } promises an area method, and a circle C and a rectangle R each implement it, as in impl Area for C. Traits can also have methods with default implementations, and they can be implemented later for types that already exist. The orphan rule, however, requires that the trait or the type be defined in your own crate, so you cannot implement someone else’s trait for someone else’s type. Traits are used together with generics. The T: Area in fn total<T: Area>(xs: &[T]) is a trait bound requiring T to be a type that implements Area. Calling total(&circles) fixes T as C, so the compiler turns x.area() into a direct call to C::area and even inlines it, producing the same machine code as hand-written code. This is called static dispatch. To achieve it, the compiler performs monomorphization, generating a separate copy of the generic function for each type used. Here, using a generic biggest on an i32 array and an f64 array produced two functions in the executable, biggest::<i32> and biggest::<f64>. It is the same approach as C++ templates, so the abstraction costs nothing at run time, but using many types increases compile time and binary size. The standard library’s traits are wired into the language: implementing Display makes a type printable with {}, implementing Iterator makes it usable in for loops, and implementing Add enables the + operator. #[derive(Debug, Clone, PartialEq, Eq, Hash)] generates implementations of such common traits automatically.', sTrait()),
    item('rs-dyn', '트레이트 객체', 'Trait objects',
      'dyn Trait는 실행 중에 타입이 정해지는 트레이트 객체예요. 데이터와 vtable 두 포인터로 된 팻 포인터로 다루고, 메서드는 vtable을 거쳐 간접 호출돼요.',
      '제네릭은 컴파일 때 타입이 하나로 정해져야 해요. 그래서 원과 사각형처럼 서로 다른 타입을 한 Vec에 섞어 담으려면 트레이트 객체가 필요해요. dyn Area는 "Area를 구현한 어떤 타입"을 뜻하고, 크기를 컴파일 때 알 수 없으므로 Box<dyn Area>나 &dyn Area처럼 포인터 뒤에 둬요. 이 포인터는 데이터를 가리키는 포인터와 vtable을 가리키는 포인터로 된 팻 포인터라서, 이 환경에서 Box<dyn Area>와 &dyn Area는 모두 16바이트였어요. vtable은 컴파일러가 (트레이트, 구체 타입) 쌍마다 하나씩 읽기 전용 메모리에 만들어 두는 표예요. 그 타입의 drop 함수, 크기와 정렬, 그리고 트레이트의 각 메서드 주소가 들어 있어요. s.area()를 부르면 vtable에서 area의 주소를 읽어 간접 호출하는데, 이것이 동적 디스패치예요. C++의 가상 함수와 비슷하지만 vptr가 객체 안이 아니라 포인터 쪽에 있어서, 같은 타입이라도 트레이트 객체로 쓸 때만 비용을 내요. 대가도 있어요. 간접 호출은 인라인할 수 없고, Box마다 따로 할당된 객체가 메모리에 흩어져 캐시에도 불리해요. 이 환경에서 도형 100만 개의 넓이를 합하는 데 enum과 match는 약 2.7ms, Box<dyn Area>는 약 4.2ms가 걸렸어요. 그래서 고르는 기준은 이래요. 변형이 정해진 닫힌 집합이면 enum이 가장 단순하고 빠르고, 속도가 최우선이면 제네릭, 플러그인처럼 나중에 다른 크레이트가 새 타입을 추가하는 열린 구조이거나 코드 크기를 줄이고 싶으면 dyn이에요. 모든 트레이트가 dyn이 될 수 있는 것은 아니에요. 제네릭 메서드가 있거나 Self를 값으로 돌려주는 메서드가 있으면 vtable을 만들 수 없어서 dyn으로 쓸 수 없는데, 이를 dyn 호환성(예전 이름은 객체 안전성)이라고 해요.',
      'dyn Trait is a trait object whose type is decided at run time. It is handled through a fat pointer of data and vtable, and methods are called indirectly through the vtable.',
      'Generics require a single type to be fixed at compile time, so mixing different types, such as circles and rectangles, in one Vec needs trait objects. dyn Area means "some type that implements Area," and since its size is unknown at compile time it sits behind a pointer, as in Box<dyn Area> or &dyn Area. That pointer is a fat pointer made of a pointer to the data and a pointer to a vtable, so here both Box<dyn Area> and &dyn Area were 16 bytes. A vtable is a table the compiler builds once per (trait, concrete type) pair in read-only memory. It holds that type’s drop function, its size and alignment, and the address of each of the trait’s methods. Calling s.area() reads area’s address from the vtable and calls it indirectly; this is dynamic dispatch. It resembles C++ virtual functions, but the vptr lives in the pointer rather than inside the object, so a type pays the cost only when used as a trait object. There is a price: indirect calls cannot be inlined, and objects allocated separately per Box are scattered through memory, which is unkind to the cache. Summing the areas of a million shapes here took about 2.7 ms with an enum and match versus about 4.2 ms with Box<dyn Area>. So the choice goes like this: an enum is simplest and fastest for a closed set of variants, generics when speed comes first, and dyn for open structures, such as plugins where other crates add new types later, or to shrink code size. Not every trait can be dyn. A trait with generic methods or with methods returning Self by value cannot form a vtable and cannot be used as dyn; this is called dyn compatibility, formerly object safety.', sDyn()),
    item('rs-generic', '제네릭과 impl Trait', 'Generics and impl Trait',
      '제네릭은 타입을 매개변수로 받아 타입마다 코드를 만드는 비용 없는 추상화예요. impl Trait로 복잡한 반환 타입을 숨기고, where 절과 연관 타입으로 관계를 표현해요.',
      '제네릭은 타입을 매개변수로 받아 여러 타입에 쓸 수 있는 코드를 만들어요. struct Stack<T> { items: Vec<T> }는 Stack<i32>로도 Stack<String>으로도 쓸 수 있고, 컴파일러는 쓰인 타입마다 알맞은 메모리 배치와 메서드를 따로 만들어요. impl<T> Stack<T> { … }는 모든 T에 대한 메서드를, impl Stack<i32> { … }는 특정 타입에만 있는 메서드를 정의해요. 표준 라이브러리의 Vec<T>, Option<T>, Result<T, E>, HashMap<K, V>가 모두 이런 제네릭 타입이에요. 반복자나 클로저를 돌려주는 함수는 실제 타입이 너무 길거나 아예 이름을 쓸 수 없어요. 이 환경에서 (0..n).filter(|x| x % 2 == 0)을 돌려주는 evens 함수의 진짜 타입은 Filter<Range<u32>, evens::{{closure}}>였어요. 이럴 때 반환 타입을 impl Iterator<Item = u32>로 쓰면 "Iterator를 구현한 어떤 타입"이라는 것만 드러내고 구체 타입을 숨길 수 있어요. 숨겨도 컴파일러는 실제 타입을 알고 있어서 정적 디스패치와 인라인이 그대로이고, 크기도 그대로 8바이트였어요. dyn과 달리 힙 할당이나 간접 호출이 없어요. 경계가 여러 개라 시그니처가 길어지면 fn show<T>(x: T) where T: Display + Debug처럼 where 절로 옮겨요. 트레이트 안에서 정하는 연관 타입도 있어요. Iterator의 type Item처럼 구현마다 하나로 정해지는 타입은, 타입 매개변수로 둘 때보다 쓰는 쪽이 간단해져요. const 제네릭은 fn sum<const N: usize>(a: [i32; N])처럼 배열 길이 같은 상수 값도 매개변수로 받아요. 제네릭은 실행 비용이 없지만, 타입마다 코드가 생기므로 많이 쓰면 컴파일 시간과 실행 파일 크기가 늘어요. 이것이 문제가 되면 일부를 dyn으로 바꿔 한 벌의 코드만 만들게 할 수 있어요.',
      'Generics take types as parameters and generate code per type, a zero-cost abstraction. impl Trait hides complicated return types, and where clauses and associated types express relationships.',
      'Generics take types as parameters to make code usable with many types. struct Stack<T> { items: Vec<T> } can be used as Stack<i32> or Stack<String>, and the compiler generates a suitable memory layout and methods for each type used. impl<T> Stack<T> { … } defines methods for every T, while impl Stack<i32> { … } defines methods for one specific type only. The standard library’s Vec<T>, Option<T>, Result<T, E> and HashMap<K, V> are all generic types like this. Functions that return iterators or closures have actual types that are too long or cannot be named at all. Here, the real type of evens, which returns (0..n).filter(|x| x % 2 == 0), was Filter<Range<u32>, evens::{{closure}}>. Writing the return type as impl Iterator<Item = u32> reveals only that it is "some type implementing Iterator" and hides the concrete type. Though hidden, the compiler knows the real type, so static dispatch and inlining remain, and the size stayed 8 bytes. Unlike dyn, there is no heap allocation or indirect call. When several bounds make a signature long, they move into a where clause, as in fn show<T>(x: T) where T: Display + Debug. Traits can also define associated types: a type fixed once per implementation, such as Iterator’s type Item, is simpler for users than an extra type parameter. Const generics take constant values such as array lengths as parameters, as in fn sum<const N: usize>(a: [i32; N]). Generics cost nothing at run time, but since code is generated per type, heavy use increases compile time and executable size. When that becomes a problem, part of the code can switch to dyn so that only one copy is generated.', sGeneric())
  ]),
  sec('rs-mem', '스마트 포인터와 메모리', 'Smart pointers and memory', '소유권을 넓히는 도구들', 'Tools that stretch ownership', '힙 값을 혼자 소유하는 Box, 참조 수로 공유하는 Rc와 Weak, 실행 중에 빌림을 검사하는 RefCell, Vec의 구조와 성장, 그리고 컴파일러 대신 사람이 증명하는 unsafe를 봐요.', 'Box, which solely owns a heap value, Rc and Weak, which share through reference counts, RefCell, which checks borrows at run time, the structure and growth of Vec, and unsafe, where a person proves what the compiler cannot.', [
    item('rs-box', 'Box', 'Box',
      'Box는 힙에 있는 값을 혼자 소유하는 8바이트 포인터예요. 재귀 타입의 크기를 정해 주고, 크기를 모르는 dyn Trait를 담는 데 써요.',
      'Box<T>는 가장 단순한 스마트 포인터예요. Box::new(5)는 i32 하나를 힙에 할당하고, 스택에는 그 값을 가리키는 8바이트 포인터 b가 놓여요. Box는 값을 혼자 소유하므로 소유권 규칙이 그대로 적용되어, 다른 변수에 대입하면 이동하고, b가 범위를 벗어나면 Drop이 힙 메모리를 해제해요. 비용은 C에서 malloc과 free를 직접 부르는 것과 같고, 가비지 컬렉터가 끼지 않아요. Box가 꼭 필요한 첫 번째 경우는 재귀 타입이에요. Rust는 모든 타입의 크기를 컴파일 때 알아야 하는데, enum List { Cons(i32, List), Nil }처럼 자기 자신을 직접 담는 타입은 크기가 무한히 커져요. 이 환경에서 이 코드는 error[E0072]: recursive type `List` has infinite size와 함께 Box, Rc, & 같은 간접 참조를 넣어 순환을 끊으라는 도움말을 냈어요. Cons(i32, Box<List>)로 바꾸면 다음 노드 자리에 크기가 정해진 8바이트 포인터가 들어가서 컴파일되고, 노드들은 힙에 따로 할당되어 포인터로 이어진 연결 리스트가 돼요. 트리, 표현식 트리 같은 재귀 자료구조가 모두 이렇게 만들어져요. 두 번째는 크기를 컴파일 때 알 수 없는 값이에요. dyn Trait 같은 트레이트 객체는 구체 타입마다 크기가 달라서 Box<dyn Trait>처럼 포인터 뒤에 둬요. 세 번째는 아주 큰 값을 옮길 때예요. 값을 이동하면 스택에서 바이트가 복사되는데, Box에 담아 두면 포인터 8바이트만 옮기면 돼요. Box는 Deref를 구현해서 *b로 안의 값을 쓰거나 b.method()처럼 안의 메서드를 바로 부를 수 있어요.',
      'A Box is an 8-byte pointer that solely owns a value on the heap. It gives recursive types a known size and holds unsized dyn Traits.',
      'Box<T> is the simplest smart pointer. Box::new(5) allocates one i32 on the heap, and on the stack sits b, an 8-byte pointer to it. Since a Box solely owns its value, the ownership rules apply as they are: assigning it to another variable moves it, and when b leaves scope, Drop frees the heap memory. The cost is the same as calling malloc and free directly in C, with no garbage collector involved. The first case that truly needs a Box is a recursive type. Rust must know every type’s size at compile time, and a type that contains itself directly, such as enum List { Cons(i32, List), Nil }, would be infinitely large. Here this code failed with error[E0072]: recursive type `List` has infinite size, plus a hint to break the cycle with indirection such as Box, Rc or &. Changing it to Cons(i32, Box<List>) puts a pointer of known size, 8 bytes, where the next node goes, so it compiles, and the nodes become a linked list allocated separately on the heap and joined by pointers. Recursive data structures such as trees and expression trees are all built this way. The second case is values whose size cannot be known at compile time: trait objects such as dyn Trait differ in size per concrete type, so they live behind a pointer as Box<dyn Trait>. The third is moving very large values. Moving a value copies its bytes on the stack, but once it is in a Box, only the 8-byte pointer moves. Box implements Deref, so *b reaches the inner value and b.method() calls the inner type’s methods directly.', sBox()),
    item('rs-rc', 'Rc와 Weak', 'Rc and Weak',
      'Rc는 참조 수를 세서 여러 소유자가 한 값을 함께 소유하게 해요. clone은 수만 올리고, 서로 가리키는 순환은 Weak로 끊어요.',
      '소유권 규칙은 주인을 하나로 정하지만, 그래프의 노드처럼 여러 곳에서 한 값을 가리키고 누가 마지막으로 쓸지 컴파일 때 알 수 없는 경우가 있어요. Rc<T>(reference counted)는 이런 공유 소유를 위한 스마트 포인터예요. Rc::new(5)는 힙에 RcBox를 만들고, 그 안에 강한 참조 수, 약한 참조 수, 값이 함께 들어 있어요. Rc 자체는 RcBox를 가리키는 8바이트 포인터예요. Rc::clone(&a)는 값을 복사하지 않고 강한 수만 1 올리는 싼 연산이라, 깊은 복사인 일반 clone과 구분하려고 Rc::clone이라고 명시적으로 쓰는 관례가 있어요. 이 환경에서 clone 후 Rc::strong_count는 2였어요. Rc가 drop될 때마다 강한 수가 1 줄고, 0이 되는 순간 안의 값이 drop돼요. Rc가 주는 것은 공유 참조뿐이라서 안의 값을 바꾸려면 RefCell과 함께 Rc<RefCell<T>>로 써요. Rc::downgrade로 만든 Weak<T>는 강한 수에 들어가지 않는 약한 참조예요. 값을 살려 두지 않으므로, 쓰기 전에 upgrade()로 Option<Rc<T>>를 얻어 아직 살아 있는지 확인해요. 이 환경에서 a와 b를 모두 drop하기 전에는 Some(5), 후에는 None이 나왔어요. Weak가 꼭 필요한 이유는 순환 참조예요. 두 노드 x와 y가 Rc로 서로를 가리키면 각자의 강한 수가 2가 되고, 범위를 벗어나 지역 변수가 사라져도 서로가 1씩 붙잡고 있어서 영원히 drop되지 않아요. 이 환경에서도 drop 메시지가 하나도 찍히지 않았어요. Rust의 메모리 안전은 이런 누수까지 막아 주지는 않으므로, 트리에서 자식은 Rc로, 부모를 가리키는 역방향 참조는 Weak로 만들어요. Rc의 수 갱신은 원자적이지 않아서 한 스레드 안에서만 쓸 수 있고, 스레드 사이에서는 같은 일을 원자적으로 하는 Arc를 써요.',
      'Rc counts references so several owners can share one value. clone only bumps the count, and Weak breaks cycles in which values point at each other.',
      'The ownership rules fix a single owner, but sometimes several places point at one value, as with graph nodes, and which of them uses it last cannot be known at compile time. Rc<T> (reference counted) is the smart pointer for such shared ownership. Rc::new(5) creates an RcBox on the heap holding the strong count, the weak count and the value together, and an Rc itself is an 8-byte pointer to the RcBox. Rc::clone(&a) copies no value; it is a cheap operation that adds 1 to the strong count, and by convention it is written explicitly as Rc::clone to distinguish it from an ordinary deep clone. Here Rc::strong_count was 2 after the clone. Each time an Rc is dropped the strong count falls by 1, and the moment it reaches 0 the inner value is dropped. An Rc hands out only shared references, so changing the inner value takes RefCell as well, in the form Rc<RefCell<T>>. A Weak<T> made with Rc::downgrade is a weak reference not counted among the strong ones. It does not keep the value alive, so before use, upgrade() yields an Option<Rc<T>> to confirm the value still lives. Here it returned Some(5) before both a and b were dropped, and None afterward. Weak is essential because of reference cycles. If two nodes x and y point at each other through Rc, each strong count becomes 2, and even after the local variables vanish at the end of scope, each holds the other at 1, so they are never dropped. Indeed not a single drop message was printed here. Rust’s memory safety does not prevent leaks like this, so in a tree, children are held by Rc and back references to parents are made Weak. Rc’s count updates are not atomic, so it can be used only within one thread; across threads, Arc does the same job atomically.', sRc()),
    item('rs-refcell', 'RefCell과 내부 가변성', 'RefCell and interior mutability',
      'RefCell은 공유 참조로도 값을 바꾸게 해 주는 내부 가변성 타입이에요. 빌림 규칙을 실행 중에 검사해서, 어기면 panic이 나요.',
      '빌림 규칙에 따르면 &T 공유 참조로는 값을 바꿀 수 없어요. 하지만 Rc로 공유하는 그래프의 노드를 고치거나, 공유된 객체 안에 캐시를 두는 것처럼 공유하면서 바꿔야 할 때가 있어요. 이를 위해 Rust는 내부 가변성(interior mutability)을 제공하고, RefCell<T>가 대표적인 타입이에요. RefCell은 &c 같은 공유 참조만 있어도 c.borrow_mut()로 안의 값에 대한 가변 참조를 얻게 해 줘요. 규칙을 없애는 것은 아니고, 빌림 규칙의 검사를 컴파일 때에서 실행 중으로 옮기는 거예요. RefCell은 현재 빌림 상태를 세는 카운터를 값과 함께 가지고 있어서, 이 환경에서 RefCell<i32>는 16바이트였어요. borrow()는 읽기 수를 1 올린 가드 Ref를, borrow_mut()는 아무도 빌리지 않았을 때만 가드 RefMut를 돌려주고, 가드가 drop되면 수가 원래대로 돌아가요. 읽기 빌림 r1이 살아 있는 동안 try_borrow_mut()를 부르면 이 환경에서 Err가 돌아왔고, borrow_mut()를 부르면 RefCell already borrowed라는 panic이 났어요. 컴파일러가 잡아 주지 못하므로, 가드를 오래 들고 있지 않고 빌림을 짧은 범위에 가두는 것이 중요해요. 흔한 조합은 Rc<RefCell<T>>예요. Rc로 여러 곳에서 공유하고 RefCell로 바꿔요. 참조를 내줄 필요 없이 값을 통째로 읽고 쓰기만 하는 Copy 타입에는 카운터가 없는 더 가벼운 Cell<T>의 get과 set을 써요. RefCell과 Cell은 스레드 사이에서 쓸 수 없고(Sync가 아님), 스레드 사이에서는 같은 역할을 하는 Mutex와 RwLock을 써요. 내부 가변성은 결국 UnsafeCell이라는 기본 타입 위에 만들어져 있어요.',
      'RefCell is an interior-mutability type that lets values change even through shared references. It checks the borrowing rules at run time, and breaking them panics.',
      'By the borrowing rules, a value cannot be changed through a shared reference &T. Yet sometimes things must be shared and changed at once, such as editing nodes of a graph shared through Rc or keeping a cache inside a shared object. For this Rust offers interior mutability, and RefCell<T> is its best-known type. With just a shared reference such as &c, RefCell lets c.borrow_mut() obtain a mutable reference to the inner value. The rules are not abolished; their checking moves from compile time to run time. A RefCell keeps a counter of its current borrow state alongside the value, so RefCell<i32> was 16 bytes here. borrow() returns a Ref guard after adding a reader, borrow_mut() returns a RefMut guard only when nobody holds a borrow, and when a guard is dropped the count goes back. Calling try_borrow_mut() while the read borrow r1 was alive returned Err here, and calling borrow_mut() panicked with RefCell already borrowed. Since the compiler cannot catch this, it matters not to hold guards for long and to confine borrows to short scopes. A common combination is Rc<RefCell<T>>: Rc shares the value from several places and RefCell changes it. For Copy types that are only read and written whole without handing out references, the lighter Cell<T>, with get and set and no counter, is used instead. RefCell and Cell cannot be used across threads (they are not Sync); across threads, Mutex and RwLock play the same role. Underneath, all interior mutability is built on a primitive type called UnsafeCell.', sRefCell()),
    item('rs-vec', 'Vec의 구조', 'Inside Vec',
      'Vec는 포인터·용량·길이 24바이트와 힙 버퍼로 돼요. 빈 Vec은 할당하지 않고, 첫 push에 4칸을 잡은 뒤 두 배씩 늘어요.',
      'Vec<T>는 Rust에서 가장 많이 쓰는 컬렉션이에요. 스택에는 힙 버퍼를 가리키는 포인터, 버퍼의 칸 수인 용량(capacity), 실제 원소 수인 길이(len)로 된 24바이트가 있고, 원소들은 힙 버퍼에 빈틈없이 연속으로 놓여요. Vec::new()는 아직 아무것도 할당하지 않아서 비용이 거의 없어요. 처음 원소를 넣을 때 버퍼를 할당하는데, 이 환경에서 Vec<i32>는 첫 push에서 용량이 4가 되었어요. 원소가 작으면 처음부터 몇 칸을 잡아 두어 아주 작은 할당이 반복되는 것을 피하는 거예요. 그 뒤로 용량이 꽉 찰 때마다 8, 16, 32, 64, 128처럼 두 배씩 늘었고, 늘어날 때마다 더 큰 버퍼를 할당하고 원소를 옮긴 뒤 옛 버퍼를 해제해요. 두 배 성장 덕분에 push 한 번의 비용은 평균 O(1)이에요. 원소 수를 미리 알면 Vec::with_capacity(n)으로 한 번에 할당해서 재할당과 복사를 없애고, 다 채운 뒤 남는 용량은 shrink_to_fit()으로 돌려줄 수 있어요. C++과 달리, 재할당될 수 있는 push를 부르는 동안 원소를 빌린 참조가 남아 있으면 빌림 검사기가 컴파일 오류를 내므로, 반복자 무효화 버그가 생기지 않아요. 원소에 접근하는 방법도 여러 가지예요. v[i]는 매번 범위를 검사해서, 넘으면 index out of bounds panic이 나요. v.get(i)는 범위를 넘으면 None을 돌려주는 Option<&T>예요. for x in &v나 v.iter()로 돌면 반복자가 범위를 이미 알고 있어 원소마다 하는 검사가 사라지고, 컴파일러가 반복문을 SIMD 명령으로 바꾸기도 해서 인덱스로 도는 것 못지않게 빨라요. 이 환경의 릴리스 빌드에서 2천만 개를 도는 데 반복자는 30ms, 인덱스 반복문은 27ms로 비슷했어요. 반복자는 범위를 넘을 일이 없어 더 안전하고 읽기 쉬워서 Rust 코드는 반복자를 즐겨 써요.',
      'A Vec is 24 bytes of pointer, capacity and length plus a heap buffer. An empty Vec allocates nothing; the first push reserves 4 slots, and capacity doubles from there.',
      'Vec<T> is the most used collection in Rust. On the stack are 24 bytes: a pointer to a heap buffer, the capacity (the number of slots in the buffer) and the length (the number of actual elements), and the elements sit contiguously in the heap buffer. Vec::new() allocates nothing yet, so it costs almost nothing. The buffer is allocated when the first element is pushed, and here a Vec<i32> reached a capacity of 4 on its first push. For small elements a few slots are reserved from the start to avoid repeated tiny allocations. After that, each time it filled up, the capacity doubled to 8, 16, 32, 64 and 128, and each growth allocates a larger buffer, moves the elements and frees the old buffer. Thanks to doubling, each push costs O(1) on average. When the element count is known in advance, Vec::with_capacity(n) allocates once and removes reallocation and copying, and spare capacity left after filling can be returned with shrink_to_fit(). Unlike in C++, if a reference borrowing an element is still alive while a possibly reallocating push is called, the borrow checker reports a compile error, so iterator-invalidation bugs cannot happen. There are several ways to reach elements. v[i] checks the bounds every time and panics with index out of bounds when exceeded. v.get(i) returns an Option<&T> that is None when out of range. Looping with for x in &v or v.iter() means the iterator already knows the bounds, so the per-element checks disappear, and the compiler may even turn the loop into SIMD instructions, making it as fast as looping by index: in a release build here, 20 million elements took 30 ms with an iterator and 27 ms with an index loop. Iterators cannot go out of range and read more clearly, which is why Rust code prefers them.', sVec()),
    item('rs-unsafe', 'unsafe', 'unsafe',
      'unsafe는 컴파일러가 확인할 수 없는 일을 프로그래머가 보증하는 구역이에요. 원시 포인터 역참조 등 다섯 가지만 허용되고, 안전한 API로 감싸 쓰는 것이 원칙이에요.',
      'Rust의 안전 보장은 컴파일러가 증명할 수 있는 범위 안에서만 작동해요. 하드웨어 직접 접근, C 라이브러리 호출, 성능을 위한 저수준 자료구조처럼 컴파일러가 확인할 수 없는 일을 하려면 unsafe가 필요해요. 원시 포인터 *const T와 *mut T는 빌림 규칙의 보호를 받지 않아서 널이거나, 해제된 메모리나 정렬이 맞지 않는 주소를 가리킬 수도 있어요. 원시 포인터를 만드는 것은 안전하지만 역참조는 위험해서, 이 환경에서 *p를 그냥 쓰자 error[E0133]: dereference of raw pointer is unsafe and requires unsafe block이 났어요. unsafe { *p }처럼 unsafe 블록 안에서는 다섯 가지가 추가로 허용돼요. 원시 포인터 역참조, unsafe 함수나 메서드 호출, 가변 정적 변수(static mut) 접근, unsafe 트레이트 구현, union 필드 읽기예요. 중요한 점은 unsafe가 빌림 검사기나 타입 검사를 끄지 않는다는 거예요. 이 다섯 가지 외의 모든 규칙은 그대로 적용되고, unsafe는 "이 부분의 안전은 내가 증명했다"는 약속일 뿐이에요. 약속이 틀리면 C와 똑같이 정의되지 않은 동작이 생겨요. 표준 라이브러리의 Vec, String, Rc, Mutex도 내부는 unsafe 코드로 만들어져 있어요. 예를 들어 v.get_unchecked(i)는 경계 검사를 건너뛰어 조금 빠르지만, i가 범위를 넘으면 메모리를 망가뜨려요. 좋은 관례는 unsafe를 가능한 한 작은 범위에 가두고, 바깥에는 어떻게 써도 안전한 API만 내보내는 거예요. unsafe 블록마다 // SAFETY: 주석으로 왜 안전한지 적고, 테스트를 Miri로 돌려 확인해요. Miri는 Rust 프로그램을 해석 실행하면서 범위 밖 접근, 해제 후 사용, 잘못된 정렬, 빌림 규칙 위반 같은 정의되지 않은 동작을 찾아 줘요.',
      'unsafe marks code where the programmer vouches for what the compiler cannot check. Only five abilities such as dereferencing raw pointers are unlocked, and the rule is to wrap it in a safe API.',
      'Rust’s safety guarantees hold only as far as the compiler can prove them. To do things it cannot verify, such as touching hardware directly, calling C libraries or building low-level data structures for performance, you need unsafe. The raw pointers *const T and *mut T are not protected by the borrowing rules and may be null or point at freed memory or misaligned addresses. Creating a raw pointer is safe, but dereferencing it is dangerous, so using *p directly here gave error[E0133]: dereference of raw pointer is unsafe and requires unsafe block. Inside an unsafe block, as in unsafe { *p }, five extra things are allowed: dereferencing raw pointers, calling unsafe functions or methods, accessing mutable statics (static mut), implementing unsafe traits and reading union fields. Importantly, unsafe does not switch off the borrow checker or type checking. Every rule beyond those five still applies, and unsafe is only a promise that "I have proven this part safe." If the promise is wrong, undefined behavior follows exactly as in C. The standard library’s Vec, String, Rc and Mutex are themselves built with unsafe code inside. For example, v.get_unchecked(i) skips the bounds check and is slightly faster, but corrupts memory if i is out of range. Good practice confines unsafe to the smallest possible area and exposes only APIs that are safe however they are used. Each unsafe block gets a // SAFETY: comment explaining why it is sound, and the tests are run under Miri to check. Miri interprets Rust programs and finds undefined behavior such as out-of-bounds access, use after free, misalignment and violations of the borrowing rules.', sUnsafe())
  ]),
  sec('rs-conc', '동시성', 'Concurrency', '두려움 없는 동시성', 'Fearless concurrency', '스레드와 move 클로저, 스레드 사이의 안전을 정하는 Send와 Sync, Arc와 Mutex, 소유권을 넘기는 채널, 지역 데이터를 빌리는 범위 스레드, 그리고 async와 퓨처를 컴파일 오류와 실측값으로 봐요.', 'Threads and move closures, Send and Sync deciding safety across threads, Arc and Mutex, channels that transfer ownership, scoped threads that borrow local data, and async and futures, with compile errors and measurements.', [
    item('rs-thread', '스레드와 move', 'Threads and move',
      'thread::spawn은 클로저를 새 OS 스레드에서 실행해요. 스레드가 더 오래 살 수 있어서 지역 변수는 move로 넘겨야 하고, join으로 결과를 받아요.',
      'Rust의 표준 스레드는 운영체제 스레드와 1:1로 대응해요. thread::spawn은 클로저를 받아 새 스레드에서 실행하고 JoinHandle을 돌려줘요. 문제는 수명이에요. 새 스레드는 그것을 만든 함수보다 오래 살 수 있어서, 클로저가 지역 변수 v를 빌리기만 하면 함수가 끝나 v가 해제된 뒤에도 스레드가 v를 쓸 수 있어요. C나 C++에서는 흔한 댕글링 버그지만, Rust는 이 환경에서처럼 error[E0373]: closure may outlive the current function, but it borrows `v`로 컴파일 단계에서 막고, move 키워드를 붙이라는 도움말까지 줘요. thread::spawn(move || v.len())은 클로저가 v의 소유권을 가져가 스레드로 옮기므로, 이후 원래 함수에서는 v를 쓸 수 없고 스레드가 끝날 때 v를 해제해요. 이렇게 spawn은 클로저가 \'static, 즉 빌린 데이터 없이 혼자 살 수 있기를 요구해요. JoinHandle의 join()은 스레드가 끝날 때까지 기다렸다가 클로저의 반환값을 Result로 돌려줘요. 스레드 안에서 panic이 나면 그 스레드만 스택을 되감으며 끝나고 프로세스 전체는 계속 살아 있으며, join()이 Err를 돌려줘서 호출자가 실패를 처리할 수 있어요. 핸들을 버리면 스레드는 떨어져 나가 계속 돌다가, main 함수가 끝나면 프로세스와 함께 종료돼요. OS 스레드는 생성과 전환에 커널이 끼고 각자 수 MB의 스택을 예약해서, 동시에 수천에서 수만 개의 작업을 다뤄야 하는 네트워크 서버에서는 async 런타임을 쓰는 것이 일반적이에요. 스레드 이름이나 스택 크기는 thread::Builder로 정할 수 있어요.',
      'thread::spawn runs a closure on a new OS thread. Since the thread may live longer, local variables must be moved in, and join collects the result.',
      'Rust’s standard threads map 1:1 to operating-system threads. thread::spawn takes a closure, runs it on a new thread and returns a JoinHandle. The issue is lifetimes. A new thread may outlive the function that created it, so if the closure merely borrows the local v, the thread could use v after the function has returned and v has been freed. That is a common dangling bug in C and C++, but Rust stops it at compile time, as here with error[E0373]: closure may outlive the current function, but it borrows `v`, along with a hint to add the move keyword. thread::spawn(move || v.len()) makes the closure take ownership of v and carry it into the thread, so the original function can no longer use v, and the thread frees v when it finishes. In this way spawn requires the closure to be \'static, able to live on its own without borrowed data. join() on the JoinHandle waits until the thread finishes and returns the closure’s value in a Result. If the thread panics, only that thread unwinds and ends while the whole process keeps running, and join() returns Err so the caller can handle the failure. If the handle is dropped, the thread detaches and keeps running until main returns and the process exits with it. OS threads involve the kernel in creation and switching and each reserves a stack of several megabytes, so network servers that juggle thousands or tens of thousands of tasks at once generally use an async runtime instead. Thread names and stack sizes can be set with thread::Builder.', sThreadR()),
    item('rs-sendsync', 'Send와 Sync', 'Send and Sync',
      'Send는 다른 스레드로 넘겨도 되는 타입, Sync는 여러 스레드가 함께 참조해도 되는 타입이에요. 컴파일러가 자동으로 판단해서 데이터 경쟁을 컴파일 때 막아요.',
      'Rust가 스레드 사이의 안전을 보장하는 핵심은 Send와 Sync라는 두 표시 트레이트예요. 메서드는 없고, 타입이 어떤 성질을 가졌는지만 표시해요. T가 Send이면 T의 소유권을 다른 스레드로 넘겨도 안전하고, T가 Sync이면 &T를 여러 스레드가 동시에 가져도 안전해요. 이 두 트레이트는 자동 트레이트라서, 구조체의 모든 필드가 Send이면 그 구조체도 자동으로 Send가 돼요. 대부분의 타입은 둘 다 만족하지만, 몇몇 타입은 일부러 빠져 있어요. Rc<T>는 참조 수를 원자적이지 않은 보통의 정수 연산으로 갱신해서, 두 스레드가 동시에 clone하거나 drop하면 수가 틀어져 이중 해제나 누수가 생길 수 있어요. 그래서 Rc는 Send도 Sync도 아니고, Rc를 스레드로 보내려 하자 이 환경에서 error[E0277]: `Rc<i32>` cannot be sent between threads safely가 났어요. 같은 일을 원자적 연산으로 하는 Arc<T>는 T가 Send와 Sync이면 둘 다 만족해서 스레드 사이에 공유할 수 있어요. 크기는 Rc와 같은 8바이트 포인터이고, 원자적 연산의 비용이 조금 더 들 뿐이에요. RefCell<T>는 빌림 수를 원자적이지 않게 세므로 다른 스레드로 넘길 수는 있지만(Send) 함께 참조할 수는 없어요(Sync 아님). Mutex<T>는 잠금으로 보호하므로 T가 Send이기만 하면 Sync가 돼요. thread::spawn은 넘기는 클로저가 Send이고 \'static이기를 요구하므로, 이 규칙을 어기는 공유는 모두 타입 검사에서 걸러져요. 결과적으로 안전한 Rust에서는 데이터 경쟁이 있는 프로그램이 아예 컴파일되지 않아요. Rust 커뮤니티는 이를 "두려움 없는 동시성(fearless concurrency)"이라고 불러요. unsafe impl Send로 직접 표시할 수도 있지만, 그때는 안전을 프로그래머가 증명해야 해요.',
      'Send marks types safe to move to another thread, and Sync marks types safe to reference from several threads at once. The compiler derives them automatically and stops data races at compile time.',
      'The core of how Rust guarantees safety between threads is two marker traits, Send and Sync. They have no methods and only mark what properties a type has. If T is Send, ownership of a T can safely move to another thread; if T is Sync, several threads can safely hold &T at the same time. Both are auto traits, so a struct whose fields are all Send is automatically Send as well. Most types satisfy both, but a few are deliberately left out. Rc<T> updates its reference count with ordinary, non-atomic integer operations, so two threads cloning or dropping at once could corrupt the count and cause a double free or a leak. That is why Rc is neither Send nor Sync, and trying to send an Rc to a thread here gave error[E0277]: `Rc<i32>` cannot be sent between threads safely. Arc<T>, which does the same job with atomic operations, is both Send and Sync when T is, so it can be shared between threads. It is the same 8-byte pointer as Rc and costs only a little more for the atomic operations. RefCell<T> counts borrows non-atomically, so it can be moved to another thread (Send) but not shared (not Sync). Mutex<T> protects its data with a lock, so it is Sync as long as T is Send. thread::spawn requires the closure it receives to be Send and \'static, so any sharing that breaks these rules is filtered out by type checking. As a result, a program with a data race simply does not compile in safe Rust, which the Rust community calls "fearless concurrency." You can mark a type yourself with unsafe impl Send, but then proving its safety is up to you.', sSendSync()),
    item('rs-arcmutex', 'Arc와 Mutex', 'Arc and Mutex',
      'Arc<Mutex<T>>는 여러 스레드가 함께 소유하며 한 번에 하나만 바꾸게 하는 기본 모양이에요. 데이터는 가드를 통해서만 닿고, 가드가 사라지면 자동으로 풀려요.',
      '여러 스레드가 같은 값을 바꿔야 할 때는 두 가지가 필요해요. 하나는 여러 스레드가 그 값을 함께 소유하는 것이고, 다른 하나는 한 번에 한 스레드만 값을 바꾸게 하는 것이에요. Rust에서는 Arc가 앞의 것을, Mutex가 뒤의 것을 맡아서 Arc<Mutex<T>>가 공유 상태를 다루는 기본 모양이 돼요. 스레드마다 Arc::clone(&c)으로 참조 수를 올린 사본을 만들어 move로 넘겨요. Rust의 Mutex는 다른 언어와 달리 보호할 데이터를 안에 품고 있어요. 데이터에 닿는 유일한 방법은 lock()이 돌려주는 MutexGuard를 통하는 것이고, 가드가 범위를 벗어나면 Drop이 자동으로 락을 풀어 줘요. 그래서 락을 잡지 않고 데이터를 건드리거나, 락을 푸는 것을 잊거나, 다른 락으로 잘못된 데이터를 보호하는 실수가 구조적으로 불가능해요. 이 환경에서 스레드 4개가 각자 10만 번씩 *c.lock().unwrap() += 1을 실행하자 결과는 정확히 400000이었고 46ms가 걸렸어요. 락을 쥐고 있는 범위가 짧을수록 경합이 줄어들어요. Rust의 Mutex에는 독(poisoning)이라는 장치도 있어요. 락을 쥔 스레드가 panic하면 데이터가 중간까지만 바뀐 상태일 수 있으므로, Mutex는 독이 든 상태가 되고 이후의 lock()은 Err(PoisonError)를 돌려줘요. 이 환경에서도 락을 쥔 채 panic한 뒤 lock()이 Err였어요. 그래서 lock().unwrap()은 다른 스레드의 panic을 이어서 전파하는 효과가 있고, 필요하면 into_inner()로 데이터를 꺼내 복구할 수 있어요. 읽기가 많고 쓰기가 드물면 여러 읽기를 동시에 허용하는 RwLock을, 단순한 카운터나 플래그는 락 없는 AtomicU64나 AtomicBool을 쓰는 편이 가벼워요. 교착 상태는 Rust도 막아 주지 못하니 락을 잡는 순서를 일정하게 지켜요.',
      'Arc<Mutex<T>> is the basic shape for threads that share ownership while only one changes the value at a time. The data is reachable only through a guard, which unlocks automatically when dropped.',
      'When several threads must change the same value, two things are needed: the threads must share ownership of the value, and only one thread at a time may change it. In Rust, Arc handles the first and Mutex the second, making Arc<Mutex<T>> the basic shape for shared state. Each thread gets a copy made with Arc::clone(&c), which raises the reference count, and receives it via move. Unlike in other languages, Rust’s Mutex holds the data it protects inside itself. The only way to reach the data is through the MutexGuard returned by lock(), and when the guard leaves scope, its Drop releases the lock automatically. Mistakes such as touching the data without the lock, forgetting to unlock, or protecting the wrong data with the wrong lock are thus impossible by construction. Here, four threads each running *c.lock().unwrap() += 1 100,000 times produced exactly 400000 in 46 ms. The shorter the span in which the lock is held, the less contention. Rust’s Mutex also has a mechanism called poisoning. If a thread panics while holding the lock, the data may be only partly updated, so the Mutex becomes poisoned and later lock() calls return Err(PoisonError). Here too, lock() returned Err after a thread panicked while holding the lock. So lock().unwrap() effectively propagates another thread’s panic, and when needed, into_inner() can take out the data for recovery. For data read often and written rarely, RwLock allows many simultaneous readers, and plain counters or flags are lighter as lock-free AtomicU64 or AtomicBool. Rust cannot prevent deadlock either, so keep a consistent order when taking locks.', sArcMutex()),
    item('rs-channel', '채널', 'Channels',
      'mpsc 채널은 여러 보내는 쪽과 하나의 받는 쪽으로 메시지를 전달해요. send는 소유권을 옮기므로 경쟁이 없고, 모든 Sender가 사라지면 받는 루프가 끝나요.',
      '공유 상태 대신 메시지로 데이터를 주고받는 방식도 Rust가 잘 지원해요. 표준 라이브러리의 std::sync::mpsc는 여러 생산자, 하나의 소비자(multi-producer, single-consumer) 채널이에요. mpsc::channel()은 Sender와 Receiver 한 쌍을 돌려주고, Sender는 clone해서 여러 스레드에 나눠 줄 수 있지만 Receiver는 하나뿐이에요. tx.send(value)는 값의 소유권을 채널로 옮겨요. 보낸 쪽은 그 값을 더 이상 쓸 수 없고, 보낸 뒤에 고치려 하면 이동된 값을 썼다는 컴파일 오류가 나요. 그래서 메시지를 주고받는 동안 두 스레드가 같은 데이터를 동시에 만지는 일이 원천적으로 불가능해요. 받는 쪽은 rx.recv()로 하나씩 받거나 for msg in rx로 계속 받아요. 이 루프는 모든 Sender가 drop되어 채널이 닫히면 끝나요. 이 환경에서 세 스레드가 세 개씩 보낸 9개의 메시지를 받은 뒤 루프가 정상적으로 끝났어요. 흔한 실수는 main이 처음 만든 원본 tx를 쥐고 있는 거예요. 이러면 Sender가 하나 남아 있어서 채널이 닫히지 않고 루프가 영원히 기다리므로, 다 나눠 준 뒤 drop(tx)로 원본을 닫아요. mpsc::sync_channel(n)은 크기가 n인 버퍼를 둔 채널로, 버퍼가 차면 보내는 쪽이 기다려 생산 속도를 조절해요. 이 환경에서 두 스레드가 채널로 값을 주고받는 왕복은 약 27µs였어요. 받는 스레드를 재우고 깨우는 데 커널이 끼기 때문인데, 같은 일을 사용자 공간에서 하는 Go의 고루틴 채널보다 훨씬 느려요. 여러 소비자나 select가 필요하면 crossbeam-channel이나 flume 크레이트를, async 코드에서는 tokio::sync::mpsc를 써요.',
      'An mpsc channel carries messages from many senders to one receiver. send transfers ownership, so nothing races, and the receiving loop ends once every Sender is gone.',
      'Rust also supports exchanging data through messages instead of shared state. The standard library’s std::sync::mpsc is a multi-producer, single-consumer channel. mpsc::channel() returns a Sender and Receiver pair; the Sender can be cloned and handed to many threads, while there is only one Receiver. tx.send(value) moves the value’s ownership into the channel. The sender can no longer use it, and trying to modify it after sending is a compile error for using a moved value. So it is impossible by construction for two threads to touch the same data at once while exchanging messages. The receiver takes messages one at a time with rx.recv() or continuously with for msg in rx. That loop ends when every Sender has been dropped and the channel closes; here, after receiving the 9 messages that three threads sent three apiece, the loop ended normally. A common mistake is for main to keep holding the original tx it created first. One Sender then remains, the channel never closes and the loop waits forever, so after handing out clones, close the original with drop(tx). mpsc::sync_channel(n) creates a channel with a buffer of size n, making senders wait when it is full and thus throttling production. A round trip between two threads over channels took about 27 µs here, because putting the receiving thread to sleep and waking it involves the kernel, which is far slower than Go’s goroutine channels doing the same in user space. For multiple consumers or select, crates such as crossbeam-channel or flume are used, and async code uses tokio::sync::mpsc.', sChannelR()),
    item('rs-scoped', '범위 스레드', 'Scoped threads',
      'thread::scope 안의 스레드는 범위가 끝나기 전에 모두 join돼요. 그래서 Arc나 move 없이 지역 데이터를 빌려 병렬로 처리할 수 있어요.',
      'thread::spawn으로 만든 스레드는 언제 끝날지 컴파일러가 알 수 없어서, 클로저가 빌린 데이터 없이 혼자 살 수 있어야(\'static) 해요. 그래서 지역 벡터를 나눠 병렬로 처리하려 해도 move로 통째로 넘기거나 Arc로 감싸야 했어요. Rust 1.63에 들어온 thread::scope는 이 문제를 풀어요. thread::scope(|s| { … })는 범위 안에서 s.spawn으로 만든 모든 스레드가, scope 함수가 돌아오기 전에 반드시 join된다는 것을 보장해요. 스레드가 범위보다 오래 살 수 없으니, 범위 밖의 지역 변수를 그냥 빌려 써도 안전해요. 이 환경에서는 data.split_at_mut(2)로 벡터를 겹치지 않는 두 개의 &mut 슬라이스로 나누고, 한 스레드는 앞 절반에 10을 곱하고 다른 스레드는 뒤 절반에 1을 더했어요. 두 스레드가 같은 벡터를 동시에 바꾸지만, 두 가변 참조가 서로 겹치지 않는다는 것을 빌림 검사기가 확인하므로 데이터 경쟁이 없어요. 같은 원소를 두 스레드에 &mut로 주려 하면 컴파일되지 않아요. scope가 돌아오는 시점에는 두 스레드가 모두 끝나고 빌림도 끝났으므로 data를 바로 다시 쓸 수 있고, 결과는 [10, 20, 4, 5]였어요. Arc도, Mutex도, 데이터 복사도 필요 없었어요. 실무에서 이런 데이터 병렬 처리는 rayon 크레이트가 더 편하게 해 줘요. iter()를 par_iter()로 바꾸기만 하면 작업 훔치기 방식의 스레드 풀이 일을 자동으로 나눠 코어 수만큼 빨라지고, 빌림 규칙 덕분에 이렇게 병렬화해도 데이터 경쟁이 생기지 않아요. 범위 스레드에서 panic이 나면 scope 함수가 그 panic을 이어서 전파해요.',
      'Threads inside thread::scope are all joined before the scope ends, so they can borrow local data without Arc or move and process it in parallel.',
      'The compiler cannot know when a thread created with thread::spawn will end, so its closure must be able to live on its own without borrowed data (\'static). Processing a local vector in parallel therefore meant moving it in wholesale or wrapping it in Arc. thread::scope, added in Rust 1.63, solves this. thread::scope(|s| { … }) guarantees that every thread created with s.spawn inside the scope is joined before the scope function returns. Since the threads cannot outlive the scope, simply borrowing local variables from outside it is safe. Here, data.split_at_mut(2) divided the vector into two non-overlapping &mut slices; one thread multiplied the first half by 10 and the other added 1 to the second half. The two threads change the same vector at the same time, yet there is no data race, because the borrow checker verifies that the two mutable references do not overlap. Trying to give the same element to two threads as &mut does not compile. By the time scope returns, both threads have finished and their borrows have ended, so data can be used again right away, and the result was [10, 20, 4, 5], with no Arc, no Mutex and no copying of data. In practice, the rayon crate makes data parallelism like this even easier: just change iter() to par_iter(), and a work-stealing thread pool divides the work automatically, speeding it up by roughly the number of cores, and thanks to the borrowing rules, parallelizing this way introduces no data races. If a scoped thread panics, the scope function propagates that panic.', sScoped()),
    item('rs-async', 'async와 퓨처', 'async and futures',
      'async fn은 상태 기계인 퓨처를 돌려주고, await하거나 poll하기 전에는 아무 일도 안 해요. 실행기는 tokio 같은 라이브러리가 제공해요.',
      'async/await는 스레드를 막지 않고 기다리는 코드를 순서대로 쓰게 해 줘요. async fn fetch(id: u32) -> Data를 호출하면 몸체가 실행되는 것이 아니라 Future를 구현한 값이 돌아와요. 컴파일러는 함수 몸체를 await 지점마다 나뉜 상태 기계(enum)로 바꾸고, await를 넘어서까지 살아 있어야 하는 지역 변수를 그 상태 안에 저장해요. 그래서 퓨처의 크기는 들고 있는 상태에 따라 달라져서, 이 환경에서 아무것도 담지 않은 퓨처는 1바이트, 1KB 버퍼를 await 너머로 들고 있는 퓨처는 1144바이트였어요. 고루틴처럼 고루틴마다 스택을 따로 두지 않는 스택 없는(stackless) 방식이라 메모리가 작게 들어요. Rust의 퓨처는 게을러요. 누군가 await하거나 poll하기 전에는 첫 줄도 실행되지 않아서, 이 환경에서 println이 든 async 블록을 만들고 await하지 않은 채 버리자 아무것도 출력되지 않았어요. 실행은 실행기(executor)가 맡아요. 실행기는 퓨처의 poll을 불러서, 끝났으면 Ready(값)를, 아직 기다리는 중이면 Pending을 받고 다른 작업으로 넘어가요. 소켓이나 타이머가 준비되면 waker가 그 작업을 다시 실행 큐에 넣어요. Rust 표준 라이브러리에는 실행기가 없어서 tokio, async-std, smol 같은 런타임을 골라 쓰는데, 가장 널리 쓰이는 tokio로 100ms씩 잠드는 작업 10만 개를 띄우자 2코어에서 전체가 162ms 만에 끝났어요. 주의할 점이 있어요. async 함수 안에서 std::thread::sleep, 큰 파일 읽기, 무거운 계산처럼 스레드를 막는 일을 하면 그 실행기 스레드의 다른 작업이 모두 멈추므로, 그런 일은 tokio::task::spawn_blocking으로 별도 스레드에 보내요. 멀티스레드 런타임에서 spawn하는 퓨처는 Send여야 해서, await 너머로 Rc 같은 값을 들고 있으면 컴파일 오류가 나요.',
      'An async fn returns a future, a state machine that does nothing until awaited or polled. The executor comes from a library such as tokio.',
      'async/await lets code that waits without blocking a thread be written in order. Calling async fn fetch(id: u32) -> Data does not run the body; it returns a value implementing Future. The compiler transforms the body into a state machine (an enum) split at each await point, storing inside the state the locals that must survive across awaits. A future’s size therefore depends on the state it holds: here a future holding nothing was 1 byte, and one keeping a 1 KB buffer across an await was 1,144 bytes. Unlike goroutines, there is no separate stack per task; it is a stackless approach, so memory stays small. Rust futures are lazy. Not even the first line runs until someone awaits or polls them, so here, creating an async block containing println and discarding it without awaiting printed nothing. Running them is the executor’s job. The executor calls a future’s poll, getting Ready(value) if it is finished or Pending if it is still waiting, in which case it moves on to other work. When a socket or timer becomes ready, a waker puts that task back on the run queue. The Rust standard library has no executor, so a runtime such as tokio, async-std or smol is chosen; with tokio, the most widely used, spawning 100,000 tasks that each sleep 100 ms finished in 162 ms total on 2 cores here. There is a caution. Doing thread-blocking work inside an async function, such as std::thread::sleep, reading a large file or heavy computation, stalls every other task on that executor thread, so such work is sent to a separate thread with tokio::task::spawn_blocking. Futures spawned on a multithreaded runtime must be Send, so holding a value such as an Rc across an await is a compile error.', sAsyncR())
  ]),
  sec('rs-tools', '도구', 'Tooling', '언어와 함께 오는 도구', 'Tools that ship with the language', '빌드와 의존성을 맡는 Cargo, 모듈과 가시성, 문서 테스트까지 포함한 cargo test, clippy와 rustfmt, 그리고 컴파일 때 코드를 만드는 매크로를 이 환경의 실제 출력으로 봐요.', 'Cargo for builds and dependencies, modules and visibility, cargo test including doc tests, clippy and rustfmt, and macros that generate code at compile time, shown with actual output from this environment.', [
    item('rs-cargo', 'Cargo와 크레이트', 'Cargo and crates',
      'Cargo는 Rust의 빌드 도구이자 패키지 관리자예요. Cargo.toml에 버전 범위를 적으면 Cargo.lock이 정확한 버전을 고정하고, --release로 최적화 빌드를 만들어요.',
      'Rust 설치에는 컴파일러 rustc와 함께 Cargo가 들어 있어요. Cargo는 빌드 도구이자 패키지 관리자라서, 새 프로젝트는 cargo new로 만들고 cargo build, cargo run, cargo test, cargo doc, cargo bench를 같은 방식으로 실행해요. C와 C++에서 CMake, 패키지 관리자, 테스트 프레임워크를 프로젝트마다 따로 고르던 일을 하나의 표준 도구가 맡는 셈이에요. 라이브러리 단위는 크레이트이고, 공개 크레이트는 crates.io 레지스트리에 올라가요. Cargo.toml의 [dependencies]에 anyhow = "1"이라고 쓰면 이것은 정확히 1이 아니라 의미적 버전 범위 ^1, 즉 1.0.0 이상 2.0.0 미만을 뜻해요. 의미적 버전 규칙에서 주 버전이 같으면 호환된다고 약속하므로, Cargo는 그 범위 안에서 가장 새 버전을 골라요. 이 환경에서는 1.0.104를 받았고, 호환되지 않는 변경이 있을 수 있는 2.0은 고르지 않아요. 처음 빌드할 때 고른 정확한 버전과 체크섬은 Cargo.lock에 기록돼요. 다음 빌드나 다른 사람의 컴퓨터, CI에서도 같은 버전을 쓰므로 빌드가 재현되고, 새 버전으로 올리려면 cargo update를 실행해요. 실행 파일을 만드는 프로젝트는 Cargo.lock을 저장소에 커밋하는 것이 권장돼요. 빌드 프로필도 알아야 해요. 기본 cargo build는 빠른 컴파일과 디버깅을 위한 dev 프로필로 최적화를 거의 하지 않고, 정수 넘침을 검사해 panic을 내요. cargo build --release는 최적화한 release 프로필이에요. 이 환경에서 2천만 개 원소를 더하는 같은 코드가 dev로 179ms, release로 30ms가 걸려 약 6배 차이가 났고, 실행 파일 크기도 4,458,400바이트에서 456,120바이트로 줄었어요. 그래서 Rust의 성능을 잴 때는 반드시 --release로 빌드해야 하고, 디버그 빌드의 느린 숫자로 언어의 속도를 판단하면 안 돼요. 여러 크레이트로 이루어진 큰 프로젝트는 워크스페이스로 묶어 하나의 Cargo.lock과 target 디렉터리를 함께 써요.',
      'Cargo is Rust’s build tool and package manager. Version ranges go in Cargo.toml, Cargo.lock pins exact versions, and --release produces optimized builds.',
      'A Rust installation includes Cargo alongside the rustc compiler. Cargo is both a build tool and a package manager, so new projects are created with cargo new, and cargo build, cargo run, cargo test, cargo doc and cargo bench all work the same way. It is one standard tool doing the job that C and C++ projects split between CMake, a package manager and a test framework, chosen separately for each project. The unit of library is the crate, and public crates are published to the crates.io registry. Writing anyhow = "1" under [dependencies] in Cargo.toml does not mean exactly 1; it means the semantic version range ^1, from 1.0.0 up to but excluding 2.0.0. Semantic versioning promises compatibility within the same major version, so Cargo picks the newest version in that range. Here it fetched 1.0.104, and 2.0, which may contain incompatible changes, is never chosen. The exact versions and checksums chosen at the first build are recorded in Cargo.lock. Later builds, other people’s machines and CI then use the same versions so builds reproduce, and cargo update moves to newer ones. Projects that build executables are advised to commit Cargo.lock to the repository. Build profiles matter too. A plain cargo build uses the dev profile, made for fast compiles and debugging, which barely optimizes and checks integer overflow, panicking on it. cargo build --release uses the optimized release profile. Here the same code summing 20 million elements took 179 ms with dev and 30 ms with release, about a 6× difference, and the executable shrank from 4,458,400 bytes to 456,120 bytes. So Rust performance must always be measured with --release, and the language’s speed should never be judged from the slow numbers of a debug build. Large projects made of several crates are grouped into a workspace that shares one Cargo.lock and one target directory.', sCargo()),
    item('rs-module', '모듈과 가시성', 'Modules and visibility',
      '크레이트 안의 코드는 모듈 트리로 나뉘고, 모든 항목은 기본이 비공개예요. pub, pub(crate)로 공개 범위를 단계별로 정하고, 바깥에서 비공개 항목을 쓰면 E0603 오류가 나요.',
      '크레이트 안의 코드는 모듈로 나뉘고, 모듈은 crate를 뿌리로 하는 이름의 트리를 이뤄요. mod net { … }처럼 그 자리에서 정의할 수도 있고, mod net;이라고만 쓰면 컴파일러가 net.rs나 net/mod.rs 파일에서 내용을 읽어 와요. 항목은 crate::net::connect 같은 절대 경로나 self, super로 시작하는 상대 경로로 가리키고, use로 경로를 현재 범위로 가져와 짧게 써요. Rust의 중요한 기본값은 모든 함수, 구조체, 필드, 모듈이 기본적으로 비공개라는 점이에요. 비공개 항목은 그것이 정의된 모듈과 그 자식 모듈에서만 보이고, 밖에서 쓰게 하려면 pub를 붙여야 해요. 구조체에 pub를 붙여도 필드는 각각 pub를 붙이기 전까지 비공개라서, 불변 조건을 지키는 생성 함수를 통해서만 값을 만들게 강제할 수 있어요. 이 환경에서 모듈 밖에서 비공개 함수 net::secret()을 부르자 error[E0603]: function `secret` is private가 났어요. 이 규칙 덕분에 공개 API는 일부러 고른 것만 남고, 내부 구현은 바깥 코드를 깨뜨릴 걱정 없이 자유롭게 바꿀 수 있어요. 공개 범위는 단계적으로 조절할 수 있어요. pub(crate)는 같은 크레이트 안에서만 보이게 해서 크레이트 내부 모듈끼리는 공유하되 라이브러리 사용자에게는 숨기고, pub(super)는 부모 모듈까지만 공개해요. 깊은 경로에 있는 항목은 pub use로 다시 내보내면 사용자가 내부 구조를 몰라도 mylib::Client처럼 짧은 경로로 쓸 수 있고, 나중에 내부 구조를 바꿔도 공개 경로는 그대로 유지돼요. 큰 프로젝트는 하나의 거대한 크레이트 대신 여러 크레이트를 워크스페이스로 묶어 컴파일 단위를 나누는데, 크레이트가 Rust의 병렬 컴파일 단위이기도 해서 빌드 시간에도 도움이 돼요.',
      'Code inside a crate is split into a tree of modules, and every item is private by default. pub and pub(crate) open visibility step by step, and using a private item from outside fails with E0603.',
      'Code within a crate is divided into modules, which form a tree of names rooted at crate. A module can be defined in place as mod net { … }, or with just mod net; the compiler reads its contents from net.rs or net/mod.rs. Items are referred to by absolute paths such as crate::net::connect or by relative paths starting with self or super, and use brings a path into the current scope so it can be written briefly. An important Rust default is that every function, struct, field and module is private. A private item is visible only within the module that defines it and that module’s children, and it must be marked pub to be used from outside. Even a pub struct keeps each field private until that field is marked pub, so construction can be forced through functions that uphold invariants. Here, calling the private function net::secret() from outside its module produced error[E0603]: function `secret` is private. Because of this rule, the public API contains only what was deliberately chosen, and the internals can change freely without fear of breaking outside code. Visibility can be tuned in steps. pub(crate) makes an item visible only within the same crate, shared among the crate’s own modules but hidden from library users, and pub(super) exposes it only to the parent module. An item deep in the tree can be re-exported with pub use so users write a short path such as mylib::Client without knowing the internal layout, and the public path stays the same even if the internals are later reorganized. Large projects split their code into several crates grouped in a workspace instead of one giant crate, which also helps build times, since the crate is Rust’s unit of parallel compilation.', sModule()),
    item('rs-test', '테스트', 'Testing',
      '#[test] 함수, tests/ 디렉터리의 통합 테스트, 문서 주석 속 예제까지 cargo test 하나로 실행해요. 이 환경에서 단위 테스트 3개와 문서 테스트 1개가 모두 통과했어요.',
      'Rust는 테스트 프레임워크를 언어와 Cargo에 내장해요. 단위 테스트는 #[test] 속성을 붙인 함수이고, 보통 같은 파일 아래쪽의 #[cfg(test)] mod tests 모듈에 모아 둬요. cfg(test) 덕분에 이 코드는 테스트를 빌드할 때만 컴파일되고, 테스트 모듈이 검사 대상 모듈의 자식이므로 비공개 함수도 직접 테스트할 수 있어요. assert!, assert_eq!, assert_ne! 매크로가 실패하면 panic이 나고, assert_eq!는 기대값과 실제값을 함께 출력해 원인을 바로 보여 줘요. 테스트 함수가 Result를 돌려주게 하면 ? 연산자도 쓸 수 있어요. #[should_panic]은 panic이 나야 통과하는 테스트로, 잘못된 입력에서 제대로 실패하는지 확인할 때 써요. 디버그 빌드는 정수 넘침을 검사하므로 255u8에 1을 더하면 attempt to add with overflow panic이 나고, 이 환경에서도 test tests::overflow_panics - should panic ... ok로 통과했어요. 상수끼리의 계산은 컴파일러가 미리 넘침을 잡아 오류를 내기 때문에 예제에서는 black_box로 값을 감췄어요. Rust만의 특징은 문서 테스트예요. /// 문서 주석 안의 코드 블록은 cargo test가 실제로 컴파일하고 실행하는 테스트가 되고, 이 환경에서도 test src/lib.rs - add (line 3) ... ok가 나왔어요. 그래서 docs.rs에 보이는 예제가 코드와 어긋나 컴파일조차 되지 않는 일이 생기지 않아요. 크레이트의 공개 API만 쓰는 통합 테스트는 tests/ 디렉터리에 파일로 두고, 각 파일이 별도의 크레이트로 컴파일돼요. cargo test는 이 세 종류를 모두 찾아 기본으로 여러 스레드에서 병렬로 실행하고, 이 환경의 결과는 test result: ok. 3 passed; 0 failed였어요. 이름의 일부를 인자로 주면 해당 테스트만 실행할 수 있어요. 성능 측정은 표준의 벤치마크 기능이 아직 불안정해서 criterion 크레이트를 많이 쓰고, 무작위 입력으로 속성을 검사하는 proptest도 널리 쓰여요.',
      '#[test] functions, integration tests in tests/ and examples inside doc comments all run with one cargo test. Here 3 unit tests and 1 doc test all passed.',
      'Rust builds its test framework into the language and Cargo. A unit test is a function marked with the #[test] attribute, usually gathered in a #[cfg(test)] mod tests module at the bottom of the same file. Thanks to cfg(test), this code is compiled only when building tests, and because the test module is a child of the module under test, private functions can be tested directly. The assert!, assert_eq! and assert_ne! macros panic on failure, and assert_eq! prints both the expected and actual values so the cause is visible at once. A test function that returns a Result can use the ? operator too. #[should_panic] marks a test that passes only if it panics, used to check that bad input fails properly. Debug builds check integer overflow, so adding 1 to 255u8 panics with attempt to add with overflow, and here it passed as test tests::overflow_panics - should panic ... ok. Arithmetic between constants is caught by the compiler ahead of time as an error, so the example hides the value with black_box. Doc tests are a distinctly Rust feature. Code blocks inside /// doc comments become tests that cargo test actually compiles and runs, and here it printed test src/lib.rs - add (line 3) ... ok. So the examples shown on docs.rs can never drift from the code to the point of not compiling. Integration tests, which use only the crate’s public API, live as files in the tests/ directory, each compiled as a separate crate. cargo test finds all three kinds and runs them in parallel on several threads by default, and the result here was test result: ok. 3 passed; 0 failed. Passing part of a name as an argument runs only matching tests. For performance measurement, the standard benchmark feature is still unstable, so the criterion crate is widely used, and proptest, which checks properties against random inputs, is popular as well.', sTestR()),
    item('rs-clippy', 'clippy와 rustfmt', 'clippy and rustfmt',
      'clippy는 컴파일은 되지만 관용적이지 않거나 실수일 가능성이 큰 코드를 짚는 공식 린터이고, rustfmt는 형식을 하나로 정해요. 둘 다 CI에서 강제하는 것이 일반적이에요.',
      'Rust 컴파일러는 이미 많은 경고를 내지만, 공식 린터 clippy는 그보다 훨씬 많은 수백 가지 규칙으로 컴파일은 되지만 관용적이지 않거나, 불필요하게 느리거나, 실수일 가능성이 큰 코드를 짚어 줘요. rustup으로 함께 설치되고 cargo clippy로 실행해요. 이 환경에서 짧은 함수 하나에 세 가지 경고가 나왔어요. 첫째, 매개변수를 &Vec<i32>로 받자 ptr_arg가 writing `&Vec` instead of `&[_]` involves a new object where a slice will do라고 알려 줬어요. &[i32] 슬라이스로 받으면 Vec뿐 아니라 배열과 다른 슬라이스도 받을 수 있어 더 일반적이에요. 둘째, for i in 0..v.len()으로 v[i]만 읽자 needless_range_loop가 the loop variable `i` is only used to index `v`라고 했어요. for x in v나 v.iter()로 바꾸면 인덱스 실수가 사라지고 경계 검사도 필요 없어져요. 셋째, if pos == true에는 bool_comparison이 equality checks against true are unnecessary라고 했어요. 경고마다 규칙 설명 문서의 링크가 붙고, cargo clippy --fix는 이 중 기계적으로 고칠 수 있는 것을 자동으로 고쳐 줘요. 규칙은 correctness, suspicious, style, complexity, perf 같은 그룹으로 나뉘고, 특정 규칙은 #[allow(clippy::...)]로 끄거나 설정 파일로 조절해요. rustfmt는 cargo fmt로 실행하는 공식 형식 도구로, Go의 gofmt처럼 코드 형식을 하나로 정해서 들여쓰기나 줄바꿈을 두고 벌이는 스타일 논쟁과 리뷰의 잡음을 없애요. 팀마다 rustfmt.toml로 몇 가지 옵션을 바꿀 수는 있지만 대부분 기본값을 그대로 써요. 보통 CI에서는 cargo fmt --check로 형식이 맞는지 확인하고, cargo clippy -- -D warnings로 모든 경고를 오류로 다뤄 빌드를 실패시켜요. 이렇게 하면 저장소의 코드가 항상 같은 형식과 같은 품질 기준을 유지해요.',
      'clippy is the official linter for code that compiles but is unidiomatic or likely a mistake, and rustfmt settles one format. Enforcing both in CI is standard practice.',
      'The Rust compiler already issues many warnings, but the official linter clippy applies hundreds more rules to flag code that compiles yet is unidiomatic, needlessly slow or likely a mistake. It is installed alongside the toolchain by rustup and run with cargo clippy. Here one short function drew three warnings. First, taking a &Vec<i32> parameter triggered ptr_arg: writing `&Vec` instead of `&[_]` involves a new object where a slice will do. Taking a &[i32] slice accepts arrays and other slices as well as a Vec, so it is more general. Second, reading only v[i] in for i in 0..v.len() triggered needless_range_loop: the loop variable `i` is only used to index `v`. Switching to for x in v or v.iter() removes index mistakes and the need for bounds checks. Third, if pos == true triggered bool_comparison: equality checks against true are unnecessary. Every warning comes with a link to the rule’s documentation, and cargo clippy --fix automatically applies the ones that can be fixed mechanically. Rules are grouped into correctness, suspicious, style, complexity, perf and others, and a specific rule can be silenced with #[allow(clippy::...)] or tuned in a configuration file. rustfmt, run as cargo fmt, is the official formatter; like Go’s gofmt, it settles a single code format and removes style debates over indentation and line breaks, along with the noise they add to review. Teams can change a few options in rustfmt.toml, but most use the defaults unchanged. CI typically verifies formatting with cargo fmt --check and fails the build by treating every warning as an error with cargo clippy -- -D warnings. This keeps the code in the repository at one format and one quality bar at all times.', sClippy()),
    item('rs-macro', '매크로', 'Macros',
      'macro_rules!로 만드는 선언적 매크로는 코드 조각을 패턴으로 받아 컴파일 때 코드를 만들어요. derive나 속성 매크로는 토큰을 받아 코드를 돌려주는 절차적 매크로예요.',
      'Rust의 매크로는 이름 뒤의 느낌표로 구별해요. 매일 쓰는 println!, vec!, format!, assert_eq!가 모두 매크로예요. 함수가 아니라 매크로인 이유는 함수로는 할 수 없는 일을 하기 때문이에요. println!은 인자 개수가 정해져 있지 않고, 형식 문자열과 인자의 개수와 타입이 맞는지를 컴파일 때 검사해요. macro_rules!로 만드는 선언적 매크로는 호출된 코드 조각을 $x:expr, $name:ident, $t:ty 같은 조각 지정자 패턴과 맞춰 보고, 일치한 첫 번째 규칙의 본문으로 그 자리에 새 코드를 만들어 넣어요. $($rest:expr),+는 쉼표로 구분된 식이 하나 이상 반복되는 패턴이라서, 인자가 몇 개든 하나의 매크로로 받을 수 있어요. 예제의 maxm!(3, 9, 4)는 두 번째 규칙에 맞아 max(3, maxm!(9, 4))로 펼쳐지고, 다시 max(3, max(9, maxm!(4)))를 거쳐 첫 번째 규칙으로 끝나요. 이 환경의 테스트에서도 결과는 9였어요. C의 #define과 크게 다른 점이 둘 있어요. Rust 매크로는 텍스트가 아니라 이미 토큰으로 나뉜 트리를 다루므로 괄호가 어긋나거나 연산자 우선순위가 뒤틀리는 전처리기 버그가 없어요. 또 위생적이라서, 매크로 안에서 만든 변수는 호출한 쪽에 같은 이름의 변수가 있어도 섞이지 않아요. 펼쳐진 결과는 보통 코드처럼 타입 검사와 빌림 검사를 받아요. 절차적 매크로는 더 강력해요. 컴파일러가 코드의 토큰 흐름을 별도 크레이트의 Rust 함수에 넘기면, 그 함수가 원하는 대로 분석해 새 코드를 돌려줘요. #[derive(Debug, Clone)]처럼 구조체에 트레이트 구현을 자동으로 만들어 주는 derive 매크로, #[tokio::main]처럼 함수를 감싸는 속성 매크로, sqlx::query!처럼 함수처럼 부르는 매크로가 있어요. serde의 직렬화도 이렇게 만들어져요. 대가는 컴파일 시간과 읽기 어려움이에요. cargo expand로 펼친 결과를 볼 수 있고, 함수나 제네릭으로 충분한 일에는 매크로를 쓰지 않는 것이 좋아요.',
      'Declarative macros built with macro_rules! take code fragments through patterns and generate code at compile time. derive and attribute macros are procedural macros that take tokens and return code.',
      'Rust macros are recognized by the exclamation mark after their name, and the everyday println!, vec!, format! and assert_eq! are all macros. They are macros rather than functions because they do things functions cannot. println! takes no fixed number of arguments and checks at compile time that the format string matches the number and types of its arguments. A declarative macro built with macro_rules! matches the code fragment it is called with against patterns of fragment specifiers such as $x:expr, $name:ident and $t:ty, and generates new code in place from the body of the first matching rule. $($rest:expr),+ is a pattern for one or more comma-separated expressions, so one macro can accept any number of arguments. In the example, maxm!(3, 9, 4) matches the second rule and expands to max(3, maxm!(9, 4)), then to max(3, max(9, maxm!(4))), and ends with the first rule. The test here produced 9. Two things set it far apart from C’s #define. Rust macros work on trees of tokens rather than text, so there are no preprocessor bugs from mismatched parentheses or twisted operator precedence. They are also hygienic, so a variable created inside a macro never mixes with a same-named variable at the call site. The expansion is type-checked and borrow-checked like ordinary code. Procedural macros are more powerful. The compiler hands the code’s token stream to a Rust function in a separate crate, which analyzes it however it likes and returns new code. There are derive macros such as #[derive(Debug, Clone)] that generate trait implementations for a struct, attribute macros such as #[tokio::main] that wrap a function, and function-like macros such as sqlx::query!. serde’s serialization is built this way. The costs are compile time and readability. cargo expand shows the expanded result, and macros are best avoided where a function or generics will do.', sMacro())
  ]),
  sec('rs-practice', '실전', 'In practice', '매일 쓰는 Rust', 'Rust in everyday code', '지연 평가하는 반복자, 세 가지 클로저 트레이트, thiserror와 anyhow로 하는 실전 오류 처리, panic과 되감기, 그리고 경계 검사부터 target-cpu까지 성능을 다루는 방법을 실측값으로 봐요.', 'Lazy iterators, the three closure traits, practical error handling with thiserror and anyhow, panics and unwinding, and tuning performance from bounds checks to target-cpu, with measurements.', [
    item('rs-iter', '반복자', 'Iterators',
      'map, filter 같은 어댑터는 계획만 세우는 지연 값이고, collect나 for 같은 소비자가 당길 때 원소가 하나씩 흘러가요. 반복자 체인은 손으로 쓴 루프만큼 빨랐어요.',
      'Rust에서 컬렉션을 다루는 기본 방법은 반복자예요. Iterator 트레이트는 다음 원소를 Option으로 돌려주는 next() 하나만 구현하면 되고, 그러면 map, filter, zip, enumerate, take, skip, fold, sum 같은 수십 개의 메서드가 기본 구현으로 따라와요. 핵심은 지연 평가예요. v.iter().map(|x| x * 2)는 아무것도 계산하지 않고, 원래 반복자와 클로저를 담은 Map이라는 값을 돌려줄 뿐이에요. 이 환경에서 map의 클로저 안에 println을 넣고 반복자를 만들기만 했을 때는 한 줄도 찍히지 않았어요. 실제 계산은 collect, sum, count, for 반복문처럼 값을 소비하는 쪽이 next()를 부를 때 일어나고, 원소는 체인 전체를 하나씩 통과해요. 출력도 created가 먼저 찍히고 그다음 map 1, map 2, map 3, 마지막에 [2, 4, 6]이 나왔어요. 단계마다 중간 Vec을 만들지 않으므로 메모리를 아끼고, 필요한 만큼만 당기므로 (1..) 같은 무한 범위도 다룰 수 있어요. (1..).filter(|n| n % 7 == 0).take(3)은 [7, 14, 21]에서 멈췄고, (1..).map(|x| x * x).find(|&y| y > 50)은 64를 찾는 순간 멈춰서 클로저가 정확히 8번만 불렸어요. 반복 방식도 세 가지가 있어요. iter()는 &T를, iter_mut()는 &mut T를, into_iter()는 T 자체를 내놓아 컬렉션을 소비해요. 성능은 비용 없는 추상화의 대표 예예요. 컴파일러가 어댑터와 클로저를 모두 인라인해 하나의 루프로 만들기 때문에, 2천만 원소에서 filter, map, sum 체인이 44ms, 같은 일을 하는 인덱스 루프도 44ms였어요(--release). 반복자는 범위를 벗어날 수 없어서 인덱스 경계 검사도 필요 없고, off-by-one 같은 실수도 줄어요. 그래서 Rust에서는 인덱스 루프보다 반복자 체인이 관용적이고, clippy도 인덱스로만 쓰는 루프를 반복자로 바꾸라고 권해요. 데이터 병렬 처리가 필요하면 rayon 크레이트의 par_iter()로 같은 체인을 여러 코어에서 실행할 수 있어요.',
      'Adapters such as map and filter are lazy values that only build a plan, and elements flow through one at a time when a consumer such as collect or for pulls them. An iterator chain ran as fast as a hand-written loop.',
      'Iterators are the basic way to work with collections in Rust. The Iterator trait requires only next(), which returns the next element as an Option, and in return dozens of methods such as map, filter, zip, enumerate, take, skip, fold and sum come with default implementations. The key is lazy evaluation. v.iter().map(|x| x * 2) computes nothing; it merely returns a value called Map holding the original iterator and the closure. Here, with a println inside the map closure, merely creating the iterator printed nothing at all. The actual computation happens when a consumer such as collect, sum, count or a for loop calls next(), and each element passes through the whole chain one at a time. The output printed created first, then map 1, map 2, map 3 and finally [2, 4, 6]. No intermediate Vec is built at each stage, which saves memory, and since only as much as needed is pulled, even infinite ranges such as (1..) can be used. (1..).filter(|n| n % 7 == 0).take(3) stopped at [7, 14, 21], and (1..).map(|x| x * x).find(|&y| y > 50) stopped the moment it found 64, calling the closure exactly 8 times. There are three ways to iterate: iter() yields &T, iter_mut() yields &mut T, and into_iter() yields T itself, consuming the collection. Performance makes iterators a prime example of a zero-cost abstraction. The compiler inlines the adapters and closures into a single loop, so over 20 million elements a filter, map and sum chain took 44 ms and an index loop doing the same took 44 ms (--release). Iterators cannot run out of range, so they need no index bounds checks and avoid mistakes such as off-by-one errors. That is why iterator chains are more idiomatic in Rust than index loops, and clippy recommends replacing loops that only index with iterators. When data parallelism is needed, the rayon crate’s par_iter() runs the same chain on several cores.', sIter()),
    item('rs-closure', '클로저와 Fn 트레이트', 'Closures and the Fn traits',
      '클로저는 캡처를 어떻게 쓰느냐에 따라 Fn, FnMut, FnOnce 중 하나가 돼요. 캡처한 값만 담은 익명 구조체라서 크기도 캡처에 따라 0바이트부터 달라졌어요.',
      '클로저는 주변 변수를 캡처할 수 있는 익명 함수예요. Rust에서 클로저는 컴파일러가 만드는 익명 구조체로, 캡처한 변수를 필드로 갖고 호출 연산자를 구현해요. 캡처한 변수를 어떻게 쓰는지에 따라 세 가지 트레이트 중 무엇을 구현할지가 자동으로 정해져요. 값을 읽기만 하면 &T로 빌려 Fn이 되고 몇 번이든 동시에 불러도 안전해요. 값을 바꾸면 &mut T로 빌려 FnMut이 되고 한 번에 한 곳에서만 부를 수 있어요. 캡처한 값을 소비하면, 예를 들어 drop하거나 다른 곳으로 이동시키면 FnOnce가 되어 한 번만 부를 수 있어요. 이 세 트레이트는 포함 관계라서 Fn인 클로저는 FnMut과 FnOnce를 받는 곳에도 넘길 수 있어요. 함수는 받을 클로저의 종류를 이 트레이트로 적고, 컴파일러가 맞는지 검사해요. 이 환경에서 Fn을 받는 함수에 n += 1처럼 값을 바꾸는 클로저를 넘기자 error[E0594]: cannot assign to `n`, as it is a captured variable in a `Fn` closure가 나며 매개변수를 FnMut로 바꾸라는 도움말이 붙었어요. move || drop(name)은 name을 소비하므로 FnOnce인데, 두 번 부르자 error[E0382]: use of moved value: `eat`와 closure cannot be invoked more than once라는 설명이 나왔어요. move 키워드는 캡처를 빌림 대신 소유로 바꿀 뿐이고, 어떤 트레이트인지는 본문이 정해요. 그래서 move 클로저도 값을 읽기만 하면 Fn이에요. 크기도 캡처가 정해요. 이 환경에서 아무것도 캡처하지 않은 클로저는 0바이트, &name 하나를 빌린 클로저는 8바이트, 두 변수를 빌린 클로저는 16바이트, String을 move한 클로저는 24바이트, i32를 move한 adder는 4바이트였어요. 클로저를 받는 방식은 두 가지예요. impl Fn이나 제네릭으로 받으면 클로저마다 코드가 따로 만들어져 호출이 인라인되고, Box<dyn Fn>으로 받으면 서로 다른 클로저를 한 타입으로 담을 수 있는 대신 vtable을 거쳐 호출해요. Box<dyn Fn>은 데이터 포인터와 vtable 포인터로 된 16바이트 팻 포인터였어요.',
      'A closure becomes Fn, FnMut or FnOnce depending on how it uses its captures. It is an anonymous struct holding only what it captured, so its size, starting from 0 bytes, varied with the captures.',
      'A closure is an anonymous function that can capture surrounding variables. In Rust, a closure is an anonymous struct generated by the compiler, with the captured variables as fields and an implementation of the call operator. How it uses its captured variables automatically decides which of three traits it implements. If it only reads them, it borrows &T and is Fn, safe to call any number of times, even concurrently. If it changes them, it borrows &mut T and is FnMut, callable from only one place at a time. If it consumes a captured value, for example by dropping it or moving it elsewhere, it is FnOnce and can be called only once. The three traits nest, so an Fn closure can also be passed where FnMut or FnOnce is expected. Functions state the kind of closure they accept with these traits, and the compiler checks the match. Here, passing a mutating closure such as n += 1 to a function that takes Fn produced error[E0594]: cannot assign to `n`, as it is a captured variable in a `Fn` closure, with a hint to change the parameter to FnMut. move || drop(name) consumes name, so it is FnOnce, and calling it twice produced error[E0382]: use of moved value: `eat` with the explanation closure cannot be invoked more than once. The move keyword only switches captures from borrowing to owning, while the body decides the trait, so a move closure that only reads is still Fn. The captures also decide the size. Here a closure capturing nothing was 0 bytes, one borrowing &name 8 bytes, one borrowing two variables 16 bytes, one moving a String 24 bytes, and the adder moving an i32 4 bytes. There are two ways to accept a closure. Taking impl Fn or a generic generates separate code per closure so calls inline, while taking Box<dyn Fn> can hold different closures as one type but calls through a vtable. The Box<dyn Fn> was a 16-byte fat pointer made of a data pointer and a vtable pointer.', sClosure()),
    item('rs-errors', '실전 오류 처리', 'Error handling in practice',
      '라이브러리는 thiserror로 구별 가능한 오류 enum을 만들고, 애플리케이션은 anyhow로 어떤 오류든 담아 context로 설명을 쌓아요. ?는 From으로 오류를 변환해 줘요.',
      'Rust의 오류는 Result 값이고, ? 연산자가 Err를 만나면 함수에서 바로 돌려줘요. 실제 프로젝트에서는 여러 출처의 오류를 어떤 타입으로 모을지가 문제인데, 흔히 두 크레이트를 함께 써요. 라이브러리는 호출자가 실패 종류에 따라 다르게 대응할 수 있도록 오류를 enum으로 정의해요. 이때 Display와 std::error::Error를 손으로 구현하는 대신 thiserror의 derive를 쓰면, 각 변형에 붙인 #[error("bad port: {0}")] 같은 문구로 Display가 만들어지고 Error 트레이트도 구현돼요. 이 환경에서 Missing 변형은 missing key `port`로, BadPort는 bad port: invalid digit found in string으로 찍혔어요. 변형의 필드에 #[from]을 붙이면 ParseIntError를 ConfigError로 바꾸는 From 구현이 생겨요. ? 연산자는 Err를 돌려줄 때 From으로 변환하므로, s.parse::<u16>()?만 써도 파싱 오류가 자동으로 BadPort가 돼요. 호출자는 match로 Err(ConfigError::BadPort(e))를 골라 처리할 수 있고, 이 환경에서는 99999를 넣자 number too large to fit in target type을 담은 BadPort가 잡혔어요. 애플리케이션은 대개 오류의 종류보다 무슨 일을 하다가 실패했는지가 중요해요. anyhow::Error는 Error를 구현한 어떤 오류든 담는 8바이트 포인터라서 함수마다 anyhow::Result<T>를 돌려주면 되고, with_context로 원인 위에 사람이 읽을 설명을 쌓을 수 있어요. 없는 파일을 읽자 Error: reading config.toml, 그 아래 Caused by: No such file or directory (os error 2)가 찍혀서 무엇을 하다 왜 실패했는지가 함께 보였어요. main이 anyhow::Result<()>를 돌려주면 Err일 때 이 메시지를 출력하고 종료 코드 1로 끝나요. RUST_BACKTRACE를 켜면 오류가 생긴 위치의 백트레이스도 붙어요. 선택 기준은 호출자예요. 호출자가 실패 종류를 구별해 다르게 행동해야 하면 thiserror로 만든 enum을, 로그에 남기거나 사용자에게 보여 주기만 하면 anyhow를 써요. 그래서 라이브러리 크레이트는 thiserror, 실행 파일은 anyhow를 쓰는 조합이 흔해요. 공개 API에 anyhow::Error를 노출하면 호출자가 오류를 구별할 수 없으므로 라이브러리에서는 피해요.',
      'Libraries build distinguishable error enums with thiserror, while applications hold any error in anyhow and stack messages with context. ? converts errors through From.',
      'Errors in Rust are Result values, and the ? operator returns from the function at once when it meets an Err. In real projects, the question is which type gathers errors from many sources, and two crates are commonly used together. Libraries define their errors as an enum so callers can respond differently by kind of failure. Instead of implementing Display and std::error::Error by hand, thiserror’s derive builds Display from text such as #[error("bad port: {0}")] on each variant and implements the Error trait. Here the Missing variant printed as missing key `port` and BadPort as bad port: invalid digit found in string. Putting #[from] on a variant’s field generates a From implementation converting ParseIntError into ConfigError. Because the ? operator converts through From when returning an Err, writing just s.parse::<u16>()? turns a parse error into BadPort automatically. Callers can pick it out with match on Err(ConfigError::BadPort(e)), and here passing 99999 was caught as a BadPort holding number too large to fit in target type. Applications usually care less about the kind of error than about what was being done when it failed. anyhow::Error is an 8-byte pointer holding any error that implements Error, so each function can simply return anyhow::Result<T>, and with_context stacks a human-readable message on top of the cause. Reading a missing file printed Error: reading config.toml followed by Caused by: No such file or directory (os error 2), showing both what was being done and why it failed. When main returns anyhow::Result<()>, an Err prints this message and the process exits with code 1. Turning on RUST_BACKTRACE also attaches a backtrace of where the error arose. The deciding factor is the caller. When callers must tell kinds of failure apart and act differently, use an enum built with thiserror, and when they only log it or show it to a user, use anyhow. That is why library crates with thiserror and executables with anyhow is a common combination. Exposing anyhow::Error in a public API leaves callers unable to distinguish errors, so libraries avoid it.', sErrors()),
    item('rs-panic', 'panic과 되감기', 'Panics and unwinding',
      '예상할 수 있는 실패는 Result, 버그는 panic이에요. panic은 기본으로 스택을 되감으며 Drop을 실행하고 종료 코드 101로 끝났고, panic = "abort"에서는 정리 없이 134로 끝났어요.',
      'Rust는 실패를 두 종류로 나눠요. 파일이 없거나, 네트워크가 끊기거나, 사용자 입력이 잘못된 것처럼 정상적인 실행 중에도 일어날 수 있는 실패는 Result로 돌려줘서 호출자가 처리하게 해요. 반대로 배열 범위를 넘거나, 절대 깨지면 안 되는 불변 조건이 깨진 것처럼 프로그램 자체의 버그는 panic으로 즉시 멈춰요. panic은 다른 언어의 예외처럼 흐름 제어에 쓰지 않고, 계속 실행하면 더 위험한 상태를 알리는 장치예요. unwrap()과 expect()도 None이나 Err이면 panic을 내므로, 테스트나 실패할 수 없음이 확실한 곳에서만 쓰고 라이브러리 코드는 Result를 돌려줘요. 이 환경에서 길이 3인 Vec에 인덱스 10으로 접근하자, C처럼 옆 메모리를 조용히 읽는 대신 index out of bounds: the len is 3 but the index is 10이라는 메시지와 파일과 줄 위치를 찍고 panic이 났어요. 그래서 안전한 Rust에서는 범위 밖 접근이 정의되지 않은 동작이나 보안 취약점으로 이어지지 않아요. panic의 기본 동작은 되감기예요. panic이 난 지점부터 스택을 거꾸로 올라가며 각 지역 변수의 Drop을 실행해서 파일을 닫고, 잠금을 풀고, 메모리를 돌려줘요. 이 환경에서도 Drop을 구현한 guard 변수의 drop guard가 찍힌 뒤 프로세스가 종료 코드 101로 끝났어요. 다른 스레드에서 난 panic은 그 스레드만 끝내고 join이 Err를 돌려주며, std::panic::catch_unwind로 되감기를 잡을 수도 있어서 C와의 경계나 스레드 풀이 panic 하나로 전체가 무너지지 않게 할 때 써요. Mutex를 잡은 채 panic이 나면 그 Mutex는 오염 상태가 되어 다음 lock()이 Err를 돌려줘요. Cargo.toml의 프로필에 panic = "abort"를 두면 되감지 않고 즉시 프로세스를 끝내요. 이 환경에서 같은 코드가 Drop을 실행하지 않고 SIGABRT로 종료 코드 134를 냈어요. 되감기용 코드와 표가 빠져 실행 파일이 조금 작아지고 빨라질 수 있지만, 정리와 catch_unwind를 포기하는 선택이라 임베디드나 크기에 민감한 환경, 또는 panic 후 즉시 재시작하는 서비스에서 써요.',
      'Expected failures are Results and bugs are panics. A panic unwinds the stack by default, running Drop and ending with exit code 101, while panic = "abort" ended with 134 and no cleanup.',
      'Rust splits failures into two kinds. Failures that can happen even in normal operation, such as a missing file, a dropped network connection or bad user input, are returned as Result for the caller to handle. Bugs in the program itself, such as indexing past an array or breaking an invariant that must never break, stop immediately with a panic. A panic is not used for control flow like exceptions in other languages; it signals that continuing would be more dangerous. unwrap() and expect() also panic on None or Err, so they are used only in tests or where failure is certain to be impossible, and library code returns Result. Here, accessing a length-3 Vec at index 10 did not silently read neighboring memory as C would; it panicked, printing the message index out of bounds: the len is 3 but the index is 10 along with the file and line. So in safe Rust, out-of-bounds access never turns into undefined behavior or a security hole. The default behavior of a panic is unwinding. Starting at the panic, the stack is walked backward, running each local variable’s Drop to close files, release locks and return memory. Here too, drop guard from a guard variable implementing Drop was printed before the process ended with exit code 101. A panic in another thread ends only that thread and makes join return Err, and std::panic::catch_unwind can catch the unwinding, which is used at boundaries with C or to keep a thread pool from collapsing over one panic. If a panic happens while a Mutex is held, that Mutex becomes poisoned and the next lock() returns Err. Putting panic = "abort" in a Cargo.toml profile ends the process immediately without unwinding. Here the same code exited via SIGABRT with code 134 without running Drop. Dropping the unwinding code and tables can make the executable slightly smaller and faster, but it gives up cleanup and catch_unwind, so it is chosen for embedded or size-sensitive environments, or for services that restart right after a panic.', sPanicR()),
    item('rs-perf', '성능 다루기', 'Tuning performance',
      '경계 검사는 대개 거의 공짜였고, 미리 할당하기와 release 프로필 설정, target-cpu가 더 큰 차이를 냈어요. 무엇보다 고치기 전에 측정해요.',
      'Rust 코드의 성능을 다룰 때 첫 규칙은 항상 --release로 빌드하고, 고치기 전에 측정하는 거예요. perf나 cargo flamegraph로 시간이 어디에 쓰이는지 보고, criterion으로 변경 전후를 통계적으로 비교해요. 흔한 걱정은 경계 검사예요. 안전한 Rust는 a[i]마다 범위를 검사하지만, 실제로는 대개 거의 공짜예요. 이 환경에서 2천만 원소의 a[i] * b[i] 인덱스 루프와 zip 반복자가 모두 16ms였고, 어셈블리를 보니 LLVM이 루프 앞에서 길이를 한 번 확인한 뒤 SIMD 명령으로 벡터화하고, 범위를 넘는 경우만 끝에서 따로 처리했어요. 컴파일러가 증명할 수 없는 임의 인덱스로 읽는 경우에도 검사 있는 버전 20ms, unsafe get_unchecked 20ms로 차이가 거의 없었어요. 분기 예측이 항상 맞기 때문이에요. 그래서 get_unchecked는 측정으로 효과가 확인된 곳에만 써요. 더 큰 차이는 보통 할당과 메모리 접근에서 나와요. Vec::new()에서 시작해 push하면 용량이 찰 때마다 더 큰 버퍼를 할당하고 원소를 복사해요. 이 환경에서 2천만 번 push가 49ms, Vec::with_capacity로 미리 잡으면 42ms였어요. 반복문 안에서 String이나 Vec을 매번 새로 만들지 말고 clear()로 재사용하는 것도 같은 원리예요. release 프로필은 더 조일 수 있어요. lto = true는 링크할 때 크레이트 경계를 넘어 인라인하고 최적화하며, codegen-units = 1은 크레이트를 여러 조각으로 나눠 병렬 컴파일하는 대신 한 덩어리로 최적화해요. 이 환경에서 실행 파일이 456KB에서 392KB로 줄었고, strip = true와 panic = "abort"까지 더하면 318KB였어요. 대신 빌드 시간이 늘어요. 마지막은 대상 CPU예요. 기본 x86-64 빌드는 모든 x86-64 CPU에서 돌아가도록 오래된 SSE2 명령까지만 써요. RUSTFLAGS="-C target-cpu=native"로 이 CPU의 AVX2와 AVX-512를 허용하자, 캐시에 들어가는 4,096개 원소의 곱셈 합을 10만 번 반복하는 계산이 88ms에서 26ms로 3.4배 빨라졌어요. 하지만 그 명령이 없는 CPU에서는 실행 파일이 아예 돌지 않으므로, 배포용으로는 x86-64-v3처럼 대상 수준을 명시하거나 실행 중에 CPU 기능을 확인해 경로를 고르는 방법을 써요.',
      'Bounds checks were usually nearly free, while preallocation, release profile settings and target-cpu made larger differences. Above all, measure before fixing.',
      'The first rules for Rust performance are to always build with --release and to measure before fixing anything. perf or cargo flamegraph shows where the time goes, and criterion compares before and after statistically. A common worry is bounds checks. Safe Rust checks the range on every a[i], but in practice this is usually nearly free. Here an a[i] * b[i] index loop and a zip iterator over 20 million elements both took 16 ms, and the assembly showed LLVM checking the length once before the loop, vectorizing with SIMD instructions and handling only the out-of-range case separately at the end. Even reads at random indices, which the compiler cannot prove safe, took 20 ms with checks versus 20 ms with unsafe get_unchecked, because the branch predictor is always right. So get_unchecked is used only where measurement confirms a benefit. Bigger differences usually come from allocation and memory access. Pushing onto a Vec started with Vec::new() allocates a bigger buffer and copies the elements every time capacity runs out. Here 20 million pushes took 49 ms, and 42 ms with Vec::with_capacity reserving up front. Reusing a String or Vec with clear() instead of creating a new one on every loop iteration follows the same principle. The release profile can be tightened further. lto = true inlines and optimizes across crate boundaries at link time, and codegen-units = 1 optimizes each crate as one unit instead of splitting it into pieces compiled in parallel. Here the executable shrank from 456 KB to 392 KB, and to 318 KB with strip = true and panic = "abort" added, at the cost of longer builds. The last lever is the target CPU. The default x86-64 build uses instructions only up to the older SSE2 so it runs on every x86-64 CPU. Allowing this CPU’s AVX2 and AVX-512 with RUSTFLAGS="-C target-cpu=native" made a computation repeating a multiply-sum over 4,096 cache-resident elements 100,000 times go from 88 ms to 26 ms, 3.4× faster. But the executable will not run at all on CPUs lacking those instructions, so distributed builds either name a target level such as x86-64-v3 or check CPU features at run time to choose a code path.', sPerfR())
  ]),
], add: {} };
